-- New B2 exam question content for M13 (Aircraft Aerodynamic Structures) and
-- M14 (Propulsion), supplied by the client as a corrected/reviewed question bank
-- specific to the official avionics (B2) exam. The source lists questions as a
-- single flat numbered pool with no subtopic breakdown, so rather than guessing
-- a subject mapping, each module gets one new catch-all subject to hold them.

ON CONFLICT (code) DO NOTHING;

-- Official exam format update per client spec (replaces the previous estimated values)
ON CONFLICT (module_code, licence_type) DO UPDATE SET
  question_count = EXCLUDED.question_count, time_limit_min = EXCLUDED.time_limit_min;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM questions q
        JOIN easa_subjects s ON s.id = q.subject_id
        WHERE s.code IN ('M13.23', 'M14.4')
    ) THEN
        RAISE NOTICE 'M13/M14 exam question bank already seeded, skipping.';
        RETURN;
    END IF;

END $$;
