INSERT INTO exam_formats (module_code, licence_type, question_count, time_limit_min) VALUES
  ('M13', 'B2', 188, 235),
  ('M14', 'B2', 32, 40)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The stall margin mode is controlled by', '[{"id": "a", "text": "EPR limits", "correct": false}, {"id": "b", "text": "Speed bug cursors", "correct": false}, {"id": "c", "text": "A O A and flap position sensors", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The versine signal is used in the', '[{"id": "a", "text": "pitch channel only", "correct": true}, {"id": "b", "text": "roll channel", "correct": false}, {"id": "c", "text": "pitch and roll channel", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Lift in a helicopter is a result of', '[{"id": "a", "text": "Angle of attack X velocity squared and forward speed", "correct": false}, {"id": "b", "text": "Angle of attack X velocity squared", "correct": true}, {"id": "c", "text": "Pitch X square root of speed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With AGC inop, sensitivity will be effected to signals with', '[{"id": "a", "text": "low signal strength", "correct": false}, {"id": "b", "text": "High signal strength", "correct": true}, {"id": "c", "text": "Both", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Voice/Range switch selected to range', '[{"id": "a", "text": "allows NAV/ADF and DME through cancelling out voice spectrum", "correct": true}, {"id": "b", "text": "allows NAV/ADF and cancels out voice spectrum", "correct": false}, {"id": "c", "text": "allows noise spectrum through", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPS L 1 and L 2 signals are', '[{"id": "a", "text": "Bi phase 50 bit/ sec", "correct": true}, {"id": "b", "text": "10.2 KHZ send rate", "correct": false}, {"id": "c", "text": "1KHz send rate", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Transmission line losses have what effect on VSWR', '[{"id": "a", "text": "Increase", "correct": false}, {"id": "b", "text": "Decrease", "correct": true}, {"id": "c", "text": "Do not affect", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ARINC 629 operates at which speed ?', '[{"id": "a", "text": "1300 Kb/s", "correct": false}, {"id": "b", "text": "1000 Kb/s", "correct": false}, {"id": "c", "text": "2000 Kb/s", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A Loran C transmission consists of', '[{"id": "a", "text": "6 pulses each 270 microseconds long", "correct": false}, {"id": "b", "text": "8 pulses each 270 microseconds long", "correct": true}, {"id": "c", "text": "6 pulses with a total pulse train length of 8.27 ms", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Water contamination in a capacitance fuel system will', '[{"id": "a", "text": "cause contents to overead", "correct": true}, {"id": "b", "text": "cause contents to under read", "correct": false}, {"id": "c", "text": "short out capacitance probe and trip CB", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Using the fast erection switch on a standby horizon prior to the flag clearing may cause', '[{"id": "a", "text": "the instrument to erect false datum", "correct": true}, {"id": "b", "text": "application of a large torque to the control phase windings causing failure", "correct": false}, {"id": "c", "text": "You must use the Fast erection switch to clear the flag", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft landing on QFE the altimeter will', '[{"id": "a", "text": "read zero on touchdown", "correct": true}, {"id": "b", "text": "read airfield height on landing", "correct": false}, {"id": "c", "text": "read local area pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ARINC 429 operates at which speed?', '[{"id": "a", "text": "12.5 kb/s or 100 kb/s", "correct": true}, {"id": "b", "text": "2 Mb/s", "correct": false}, {"id": "c", "text": "1.3 Mb/s", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On a Cat 3 B landing the localizer signal is used at which phase?', '[{"id": "a", "text": "Rollout", "correct": true}, {"id": "b", "text": "Flare", "correct": false}, {"id": "c", "text": "Touchdown", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The glideslope signal integrator', '[{"id": "a", "text": "maintains glideslope signal", "correct": true}, {"id": "b", "text": "increases glideslope signal", "correct": false}, {"id": "c", "text": "decreases glideslope signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the maximum value of installation tester that may be used on a fuel contents system?', '[{"id": "a", "text": "300 Volt", "correct": false}, {"id": "b", "text": "250 Volt", "correct": false}, {"id": "c", "text": "You cannot use one on the fuel contents system", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A blade of a Helicopter Main Rotor is', '[{"id": "a", "text": "highly cambered", "correct": false}, {"id": "b", "text": "symmetrically camber", "correct": true}, {"id": "c", "text": "reverse camber", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A Mode S equipped aircraft has its RA area breached by a Mode A only equipped aircraft. What warning does the Mode S aircraft get?', '[{"id": "a", "text": "TA visual and Traffic Traffic aural warning", "correct": true}, {"id": "b", "text": "RA visual and climb or descend aural warning", "correct": false}, {"id": "c", "text": "ATA visual warning only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The capacitance fuel contents system works on the principle of', '[{"id": "a", "text": "capacitive reactance", "correct": false}, {"id": "b", "text": "resistance", "correct": false}, {"id": "c", "text": "capacitance", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Rad Alt failure effects which system?', '[{"id": "a", "text": "Mode S transponder", "correct": false}, {"id": "b", "text": "GPWS", "correct": true}, {"id": "c", "text": "nav management systems", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Man made noise causes interference', '[{"id": "a", "text": "mainly above 12 Mhz", "correct": false}, {"id": "b", "text": "only in the LF band", "correct": false}, {"id": "c", "text": "mainly below 12 Mhz", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The frequency spectrum of noise is', '[{"id": "a", "text": "infinitely wide", "correct": true}, {"id": "b", "text": "restricted to the audio band", "correct": false}, {"id": "c", "text": "restricted to the HF band", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A receiver with a high IF will successfully reject', '[{"id": "a", "text": "the adjacent/image frequency", "correct": false}, {"id": "b", "text": "the 2nd channel/image frequency", "correct": true}, {"id": "c", "text": "the 2nd channel/adjacent frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A radar pulse takes 308 microseconds to return, what is the target distance', '[{"id": "a", "text": "12.5 Nautical miles", "correct": false}, {"id": "b", "text": "25 Nautical miles", "correct": true}, {"id": "c", "text": "30 Nautical miles", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Delayed Automatic Gain Control is inoperative, the sensitivity of the receiver will', '[{"id": "a", "text": "decrease for low signal", "correct": false}, {"id": "b", "text": "increase for low signal", "correct": false}, {"id": "c", "text": "increase for high signal", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Single Side Band filters are', '[{"id": "a", "text": "3 Khz", "correct": true}, {"id": "b", "text": "1 Khz", "correct": false}, {"id": "c", "text": "6 Khz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The loop aerial polar diagram is a', '[{"id": "a", "text": "c ardioid", "correct": false}, {"id": "b", "text": "figure 8", "correct": true}, {"id": "c", "text": "c ircle", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The relationship between LORAN master and slave transmitters. Master frequency', '[{"id": "a", "text": "higher than slave", "correct": false}, {"id": "b", "text": "lower than slave", "correct": false}, {"id": "c", "text": "same as slave", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is needed for RHO-RHO navigation?', '[{"id": "a", "text": "2 DME signals", "correct": true}, {"id": "b", "text": "1 VOR and", "correct": false}, {"id": "c", "text": "1 VOR /DME signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With an ATC code of 0600 selected, the pulses transmitted are', '[{"id": "a", "text": "B 2 and B 4", "correct": true}, {"id": "b", "text": "B 1 and B 5", "correct": false}, {"id": "c", "text": "B 0 and B 6", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Tail rotor effects the helicopter in', '[{"id": "a", "text": "Vertical", "correct": false}, {"id": "b", "text": "Horizontal", "correct": true}, {"id": "c", "text": "Pitch and Roll", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In colour WXR AGC is set', '[{"id": "a", "text": "in workshop", "correct": false}, {"id": "b", "text": "automatically on receiver noise level", "correct": true}, {"id": "c", "text": "by operator on manually adjusted gain control", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is Track angle?', '[{"id": "a", "text": "The angle, measured clockwise, between true north and the aircraft ground track", "correct": true}, {"id": "b", "text": "The angle, measured clockwise, between true north and the aircraft longitudinal axis", "correct": false}, {"id": "c", "text": "The angle between true heading (HGD) and ground track", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is an Ideal VSWR on a Radio Transmission line?', '[{"id": "a", "text": "1:1", "correct": true}, {"id": "b", "text": "2:1", "correct": false}, {"id": "c", "text": "1.5:1", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On an FMCS CDU, you can select', '[{"id": "a", "text": "N 1 Thrust", "correct": true}, {"id": "b", "text": "VNAV", "correct": false}, {"id": "c", "text": "VOR", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'To check side lobe suppression', '[{"id": "a", "text": "select ATC on ASP", "correct": false}, {"id": "b", "text": "use a ramp test set", "correct": true}, {"id": "c", "text": "carry out a self test", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A valid interrogation will', '[{"id": "a", "text": "disable the RX, enable the encoder and disable the DME", "correct": true}, {"id": "b", "text": "enable the RX, disable the encoder and disable the DME", "correct": false}, {"id": "c", "text": "disable the R", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When calibrating an electronic fuel capacitance indicating system, what piece of test equipment would you use?', '[{"id": "a", "text": "a bridge", "correct": false}, {"id": "b", "text": "a decade", "correct": true}, {"id": "c", "text": "a potentiometer", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'VHF transmitter output impedance to match with antenna for maximum power transfer is', '[{"id": "a", "text": "50 ohms", "correct": true}, {"id": "b", "text": "25 to 75 ohms", "correct": false}, {"id": "c", "text": "129 ohms", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Radio waves are said to have line-of-sight propagation', '[{"id": "a", "text": "above about 100 MHz", "correct": true}, {"id": "b", "text": "not below 1000 MHz", "correct": false}, {"id": "c", "text": "from about 10 MHz upwards", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Glide slope gain programming is based on', '[{"id": "a", "text": "pressure altitude", "correct": false}, {"id": "b", "text": "altitude above MSL and radio altitude", "correct": false}, {"id": "c", "text": "radio altitude", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The Glide-slope signal integrator', '[{"id": "a", "text": "maintains the glide- slope signal", "correct": true}, {"id": "b", "text": "increases the glide-slope signal", "correct": false}, {"id": "c", "text": "decreases the glide-slope signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the static pressure is varied at too great a rate, the instrument that s most affected is the', '[{"id": "a", "text": "rate of change indicator", "correct": true}, {"id": "b", "text": "altimeter", "correct": false}, {"id": "c", "text": "airspeed indicator", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The speech clipping modulating circuit', '[{"id": "a", "text": "increases the average depth of modulation", "correct": true}, {"id": "b", "text": "clips high amplitude signals", "correct": false}, {"id": "c", "text": "cuts out high tone sounds", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The ATC aerial has a polar diagram which is', '[{"id": "a", "text": "directional", "correct": false}, {"id": "b", "text": "omni-dirrectional", "correct": true}, {"id": "c", "text": "limacon shaped", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A padder capacitor has most efficiency at', '[{"id": "a", "text": "the lowest frequency of the L O", "correct": true}, {"id": "b", "text": "the middle frequency of the L O", "correct": false}, {"id": "c", "text": "the highest frequancy of the L O", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Voice clipping', '[{"id": "a", "text": "increases the depth of modulation", "correct": false}, {"id": "b", "text": "decreases the depth of modulation of high amplitude voice signals", "correct": false}, {"id": "c", "text": "maintains an average depth of modulation", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Flight Director bars controls move up in slow increments, what controls their rate/speed?', '[{"id": "a", "text": "Rate feedback", "correct": true}, {"id": "b", "text": "Position feedback", "correct": false}, {"id": "c", "text": "Instrument amplifier gain", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What aircraft system supplies horizon?', '[{"id": "a", "text": "Generator bus", "correct": false}, {"id": "b", "text": "Normal power, then switches to emergency supply in an emergency", "correct": true}, {"id": "c", "text": "Battery Bus", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If a fault is detected during an autoland approach, the system will totally disconnect if it is a', '[{"id": "a", "text": "triplex system", "correct": false}, {"id": "b", "text": "duplex system", "correct": true}, {"id": "c", "text": "dual/dual system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An autoland is carrid out in which sequence', '[{"id": "a", "text": "GS capture, LOC capture, attitude hold, flare", "correct": false}, {"id": "b", "text": "LOC capture, GS capture, Attitude hold, Flare", "correct": true}, {"id": "c", "text": "LOC capture, GS capture, Flare, Attitude hold", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Signals used during the flare are', '[{"id": "a", "text": "GS and rad alt", "correct": false}, {"id": "b", "text": "GS and integrated pitch", "correct": false}, {"id": "c", "text": "Rad alt and integrated pitch", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Man made noise', '[{"id": "a", "text": "mainly above 12mhz", "correct": false}, {"id": "b", "text": "only in the LF band", "correct": false}, {"id": "c", "text": "mainly below 12 mhz", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An I F amplifier unit consist of four amplifiers. The amplifiers are normally coupled by', '[{"id": "a", "text": "resistor/capacitor coupling", "correct": false}, {"id": "b", "text": "pure resistor coupling", "correct": false}, {"id": "c", "text": "transformer coupling", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A receiver with a high I F will successfully reject', '[{"id": "a", "text": "the adjacent/image frequency", "correct": false}, {"id": "b", "text": "the 2nd channel/image frequency", "correct": true}, {"id": "c", "text": "the 2nd channel/adjacent frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Vortex ring start requires', '[{"id": "a", "text": "retreating blade stall", "correct": false}, {"id": "b", "text": "advancing blade stall", "correct": false}, {"id": "c", "text": "power on descent", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The integrity of an auotpilot must be increased when the aircraft is flying at', '[{"id": "a", "text": "higher speeds", "correct": false}, {"id": "b", "text": "lower speeds", "correct": false}, {"id": "c", "text": "approach and landing phases", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An integrated autoland system has been selected to Go-around during the autoland phase, the aircraft will', '[{"id": "a", "text": "increase speed", "correct": false}, {"id": "b", "text": "increase speed and rotate nose up", "correct": true}, {"id": "c", "text": "rotate nose up", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Rollout guidance by the rudder is effective to about', '[{"id": "a", "text": "80 knots", "correct": true}, {"id": "b", "text": "110 knots", "correct": false}, {"id": "c", "text": "30 knots", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Delayed Automatic Gain Control is inoperative, the sensitivity of the receive', '[{"id": "a", "text": "decrease for low signal", "correct": false}, {"id": "b", "text": "increase for low signal", "correct": false}, {"id": "c", "text": "increase for high signal", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Single Side Band filters are', '[{"id": "a", "text": "3 Khz", "correct": true}, {"id": "b", "text": "1 Khz", "correct": false}, {"id": "c", "text": "6 Khz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Air density compensation requires', '[{"id": "a", "text": "OAT", "correct": false}, {"id": "b", "text": "altitude", "correct": false}, {"id": "c", "text": "altitude and OAT", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A quartz crystal has the characteristics of a', '[{"id": "a", "text": "resistive bridge network", "correct": false}, {"id": "b", "text": "high `Q` resonant circuit", "correct": true}, {"id": "c", "text": "pair of tuned circuits", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which of the following has the best frequency stability?', '[{"id": "a", "text": "Hartley", "correct": false}, {"id": "b", "text": "Colpitts", "correct": true}, {"id": "c", "text": "Tuned collector tuned base", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Tx output stages are normally run in class C', '[{"id": "a", "text": "because the efficiency is high", "correct": true}, {"id": "b", "text": "so that the output is rich in harmonics", "correct": false}, {"id": "c", "text": "as higher gains can be obtained", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When can the FMS be engaged with the autothrottle?', '[{"id": "a", "text": "Before takeoff", "correct": true}, {"id": "b", "text": "After takeoff", "correct": false}, {"id": "c", "text": "Only with the autopilot engaged", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a dual FMS, a failure of one computer will result in', '[{"id": "a", "text": "COMPLETELY blank display on one CDU", "correct": false}, {"id": "b", "text": "down-grade of the landing category", "correct": false}, {"id": "c", "text": "no effect on the CDU", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The aircraft is programmed to leave the glideslope at', '[{"id": "a", "text": "300 ft", "correct": false}, {"id": "b", "text": "the decrab phase", "correct": false}, {"id": "c", "text": "the start of flare", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'At its resonant frequency, a parallel tuned circuit', '[{"id": "a", "text": "offers minimum impedance", "correct": false}, {"id": "b", "text": "has minimum voltage developed across it", "correct": false}, {"id": "c", "text": "has maximum circulating currents", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The RF resistance of an inductor', '[{"id": "a", "text": "decreases as frequency is increased", "correct": false}, {"id": "b", "text": "increases as frequency is increased", "correct": true}, {"id": "c", "text": "is independent of frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Crystals operate reliably at fundamental frequencies up to', '[{"id": "a", "text": "1000 MHz", "correct": false}, {"id": "b", "text": "100 MHz", "correct": false}, {"id": "c", "text": "30 MHz", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'At its resonant frequency, a parallel tuned circuit has', '[{"id": "a", "text": "maximum impedance", "correct": true}, {"id": "b", "text": "minimum impedance", "correct": false}, {"id": "c", "text": "the same impedance as at any other frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft increases in altitude, the ASI indication remains constant, what will happen to the True airspeed value?', '[{"id": "a", "text": "Increase", "correct": true}, {"id": "b", "text": "Decrease", "correct": false}, {"id": "c", "text": "Remain the same", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A Mach meter', '[{"id": "a", "text": "compensates for square law", "correct": true}, {"id": "b", "text": "does not compensate for square law", "correct": false}, {"id": "c", "text": "uses a spring and bar", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The distance over which VHF communication may be achieved is limited', '[{"id": "a", "text": "by local weather conditions in the troposphere", "correct": false}, {"id": "b", "text": "to radio line of sight", "correct": true}, {"id": "c", "text": "to conditions in the ionosphere", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When terminating an aluminium cable, what preparations would be carried out before crimping?', '[{"id": "a", "text": "Just terminate", "correct": false}, {"id": "b", "text": "Apply a mixture of 50% petroleum jelly and zinc oxide", "correct": true}, {"id": "c", "text": "Degrease spripped cable", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How can ambiguity be avoided during the test of a microwave landing system?', '[{"id": "a", "text": "Reverse the phases", "correct": false}, {"id": "b", "text": "TO/FRO", "correct": false}, {"id": "c", "text": "Note scan cycle start time", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What does a current limiter fuse do?', '[{"id": "a", "text": "Limit current to a predetermined level to prevent circuit damage", "correct": true}, {"id": "b", "text": "Allow high current to flow for 5 seconds", "correct": false}, {"id": "c", "text": "React when the circuit gets warm", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The stability of an RF oscillator can be improved by', '[{"id": "a", "text": "direct coupling to an RF amplifier", "correct": false}, {"id": "b", "text": "a buffer amplifier", "correct": true}, {"id": "c", "text": "tight coupling to an RF amplifier", "correct": false}]'::jsonb, '{B2}'),
