    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What type of signal is used for trigger height trip signals?', '[{"id": "a", "text": "Switchable d.c", "correct": true}, {"id": "b", "text": "Switchable a.c", "correct": false}, {"id": "c", "text": "variable d.c", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How does the crew select decision height?', '[{"id": "a", "text": "selected on the main altimeter", "correct": false}, {"id": "b", "text": "Selected on the radio al", "correct": true}, {"id": "c", "text": "selecting a switch on the control panel", "correct": false}]'::jsonb, '{B2}'),
