    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The frequency range 300KHz-3 MHz is called the', '[{"id": "a", "text": "LF band", "correct": false}, {"id": "b", "text": "MF band", "correct": true}, {"id": "c", "text": "VHF band", "correct": false}]'::jsonb, '{B2}'),
