    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a triplex system, if an ILS receiver fails before localizer capture', '[{"id": "a", "text": "No auto land", "correct": false}, {"id": "b", "text": "Reverts to cat II", "correct": false}, {"id": "c", "text": "Continues to auto land", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Slats, when stowed, make up part of the wing', '[{"id": "a", "text": "trailing edge", "correct": false}, {"id": "b", "text": "leading edge lower surface", "correct": false}, {"id": "c", "text": "leading edge upper surface", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ADF quadrantal error will be at', '[{"id": "a", "text": "0 Degrees", "correct": false}, {"id": "b", "text": "45 Degrees", "correct": true}, {"id": "c", "text": "90 Degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Cat 2 RVR if the alert height is 100 feet will be', '[{"id": "a", "text": "300 m", "correct": true}, {"id": "b", "text": "400 m", "correct": false}, {"id": "c", "text": "800 m", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An anti-servo tab', '[{"id": "a", "text": "assists the pilot to move the controls back to neutral", "correct": true}, {"id": "b", "text": "moves in the same direction as the control surface to assist the pilot", "correct": false}, {"id": "c", "text": "moves in the opposite direction to the control surface to assist the pilot", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An ASI compressibility error correction will be', '[{"id": "a", "text": "Positive", "correct": false}, {"id": "b", "text": "Negative", "correct": true}, {"id": "c", "text": "Both", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A GNS satellite system transmis', '[{"id": "a", "text": "vertically polarise", "correct": false}, {"id": "b", "text": "horizontally polarise", "correct": false}, {"id": "c", "text": "right hand circular", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Airspeed hold is a', '[{"id": "a", "text": "pitch mode", "correct": true}, {"id": "b", "text": "lateral mode", "correct": false}, {"id": "c", "text": "heading mode", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The auto gain voltage of weather radar is set', '[{"id": "a", "text": "in the workshop", "correct": true}, {"id": "b", "text": "by the manufacturer", "correct": false}, {"id": "c", "text": "by adjusting the gain control until optimum picture quality is obtained", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When carrying out an autoland approach, VNAV is de-selected. The aircraft will enter MCP SPD mode when', '[{"id": "a", "text": "APP switch is pressed", "correct": false}, {"id": "b", "text": "the aircraft captures the glideslope", "correct": true}, {"id": "c", "text": "the aircraft receives the first ILS signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A split flap', '[{"id": "a", "text": "forms part of the leading edge`s lower surface when retracted", "correct": false}, {"id": "b", "text": "forms part of the trailing edge`s upper surface when retracted", "correct": false}, {"id": "c", "text": "forms part of the trailing edge`s lower surface when retracted", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'TCAS will issue a traffic advisory if', '[{"id": "a", "text": "aircraft are within 6 nautical miles laterally and 1200 feet vertically of each other", "correct": false}, {"id": "b", "text": "a collision is within 25 -35 seconds of occurring", "correct": false}, {"id": "c", "text": "a collision is within 35 -40 seconds of occurring", "correct": true}]'::jsonb, '{B2}'),
