    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Parallel distribution systems can typically found on all', '[{"id": "a", "text": "twin-engined aircraft", "correct": false}, {"id": "b", "text": "aircraft with 3 or more engines", "correct": false}, {"id": "c", "text": "aircraft with 4 or more engines", "correct": true}]'::jsonb, '{B2}'),
