    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Paralleling in AC constant frequency is affected by', '[{"id": "a", "text": "contactors", "correct": false}, {"id": "b", "text": "Generator Control Unit (GCU)", "correct": true}, {"id": "c", "text": "But Tie Bar (BTB)", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If voltage and frequency of the generator drop to zero in flight, it would be an indication that the', '[{"id": "a", "text": "Phase sequence detection circuit has operated", "correct": false}, {"id": "b", "text": "CSD drive shaft has sheared", "correct": true}, {"id": "c", "text": "bus tie interlock is inoperative", "correct": false}]'::jsonb, '{B2}'),
