    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'During a system overload, load sharing will first affect', '[{"id": "a", "text": "galley servic", "correct": true}, {"id": "b", "text": "IFE", "correct": false}, {"id": "c", "text": "first officers transfer bus", "correct": false}]'::jsonb, '{B2}'),
