    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A DME receives a ground transponder reply after 2472 microseconds, the slant range to the transponder is approximately', '[{"id": "a", "text": "196 nm", "correct": true}, {"id": "b", "text": "200 nm", "correct": false}, {"id": "c", "text": "200 statute miles", "correct": false}]'::jsonb, '{B2}'),
