    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When using the GPS', '[{"id": "a", "text": "database card must be replaced every 28 days", "correct": false}, {"id": "b", "text": "once the database card has expired the system will continue to operate with a warning message", "correct": true}, {"id": "c", "text": "once the database expires the system will not operate", "correct": false}]'::jsonb, '{B2}'),
