    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An isotropic radiator', '[{"id": "a", "text": "is an end fed p/ 2 unipole", "correct": false}, {"id": "b", "text": "has a perfectly spherical radiation pattern", "correct": true}, {"id": "c", "text": "has a cardiod shaped polar diagram", "correct": false}]'::jsonb, '{B2}'),
