    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the 90 Hz tone predominates in a localizer receiver ,the deviation indicator will show', '[{"id": "a", "text": "the flag", "correct": false}, {"id": "b", "text": "fly right", "correct": true}, {"id": "c", "text": "fly left", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The components of an ILS are:', '[{"id": "a", "text": "A localizer and a glide slope", "correct": false}, {"id": "b", "text": "A localizer, a glide slope and the marker beacons", "correct": true}, {"id": "c", "text": "A localizer and the marker beacons", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In ILS, the glide slope provides', '[{"id": "a", "text": "lateral steering", "correct": false}, {"id": "b", "text": "vertical steering", "correct": true}, {"id": "c", "text": "distance checks", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A secondary surveillance radar (SSR) interrogation operates on', '[{"id": "a", "text": "a frequency of 1030 MHz and pulse spacing of 20.3 microseconds", "correct": false}, {"id": "b", "text": "a frequency of 1030 MHz and pulse spacing depending on mode of interrogation", "correct": true}, {"id": "c", "text": "a frequency of 1090 MHz and pulse spacing 20.3 microseconds", "correct": false}]'::jsonb, '{B2}'),
