    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Differential protection in an AC system protects against', '[{"id": "a", "text": "A reverse current flowing from the battery", "correct": false}, {"id": "b", "text": "short circuits", "correct": false}, {"id": "c", "text": "line-line, line-line-line, line-earth faults", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The power factor of an AC generator identifies the proportion of', '[{"id": "a", "text": "apparent power from the generator that does work", "correct": true}, {"id": "b", "text": "reactive power from the generator that does work", "correct": false}, {"id": "c", "text": "real power from the generator that does work", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The control of hydraulically powered emergency electrical generator frequency is by', '[{"id": "a", "text": "angle of swash plate", "correct": true}, {"id": "b", "text": "IDG", "correct": false}, {"id": "c", "text": "restriction valve", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Inductive reactive load causes', '[{"id": "a", "text": "no effect on torque but produces extra heat dissipated", "correct": true}, {"id": "b", "text": "increase in torque and increase in heat dissipated", "correct": false}, {"id": "c", "text": "increase in torque only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Increasing the real load primarily', '[{"id": "a", "text": "decreases frequency", "correct": true}, {"id": "b", "text": "decreases output voltage", "correct": false}, {"id": "c", "text": "increases output voltage and increases frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Paralleled relay for DC system is energised and connected by', '[{"id": "a", "text": "voltage coil", "correct": false}, {"id": "b", "text": "current coil", "correct": false}, {"id": "c", "text": "voltage and current coil", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a transistor voltage regulator the voltage output is controlled by', '[{"id": "a", "text": "transformers and transistors", "correct": false}, {"id": "b", "text": "diodes and transformers", "correct": false}, {"id": "c", "text": "zeners and transistors", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The output of a carbon pile regulator with no variation of loading is', '[{"id": "a", "text": "stationary", "correct": true}, {"id": "b", "text": "fluctuating", "correct": false}, {"id": "c", "text": "pulse width modulating", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a carbon pile regulator the resistive element is', '[{"id": "a", "text": "in series with the field and changes resistance with changing length", "correct": false}, {"id": "b", "text": "in series with the field and changes resistance with surface area contact", "correct": true}, {"id": "c", "text": "in parallel with the field and changes resistance with changing length", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Battery charging procedures can be found in ATA', '[{"id": "a", "text": "Chapter 24 Section 21", "correct": false}, {"id": "b", "text": "Chapter 24 Section 31", "correct": true}, {"id": "c", "text": "Chapter 31 Section 21", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If an aircraft has no battery charger the battery is charged by', '[{"id": "a", "text": "constant voltage", "correct": true}, {"id": "b", "text": "constant current", "correct": false}, {"id": "c", "text": "constant current until a predetermined limit when it automatically switches to constant voltage", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Maximum battery temperature on charging before protection circuit starts is', '[{"id": "a", "text": "115 degrees F", "correct": false}, {"id": "b", "text": "144 Degrees F", "correct": true}, {"id": "c", "text": "144 Degrees C", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the small pin on the DC ground power connector?', '[{"id": "a", "text": "Ground or earth", "correct": false}, {"id": "b", "text": "Positive to battery relay", "correct": false}, {"id": "c", "text": "Positive to external power relay", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When installing multiple batteries on aircraft they are connected in', '[{"id": "a", "text": "parallel", "correct": true}, {"id": "b", "text": "series", "correct": false}, {"id": "c", "text": "either parallel or series and switched between as an option", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Battery trays are', '[{"id": "a", "text": "metal for earthing purposes", "correct": false}, {"id": "b", "text": "metal with PVC coating and anti corrosive paint", "correct": true}, {"id": "c", "text": "absorbent to soak up electrolyte", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A shunt wound generator fitted on an aircraft,a preset potentiometer is fitted', '[{"id": "a", "text": "in series with the field winding", "correct": true}, {"id": "b", "text": "in parallel with the field winding", "correct": false}, {"id": "c", "text": "in series with the generator output", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'on a VSI fitted on an aircraft, for climb and descent indication', '[{"id": "a", "text": "a set screw is provided for zero adjustment", "correct": true}, {"id": "b", "text": "it does not have any adjustment", "correct": false}, {"id": "c", "text": "a set screw is provided for climb/descent increments", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The manufacturer of a pitot head gave a specification indicating 2 inches dia. This is the', '[{"id": "a", "text": "opening dia. of pitot head", "correct": false}, {"id": "b", "text": "internal dia of pitot head where air stagnates", "correct": false}, {"id": "c", "text": "external dia of pitot head", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Radar beamwidth improves', '[{"id": "a", "text": "range resolution", "correct": false}, {"id": "b", "text": "range accuracy", "correct": false}, {"id": "c", "text": "bearing resolution", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When an hydraulic system is un pressurized, the position of flight control surfaces are', '[{"id": "a", "text": "down", "correct": false}, {"id": "b", "text": "neutral", "correct": false}, {"id": "c", "text": "droop", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Oscillation and hunting of flight control surface are prevented by', '[{"id": "a", "text": "Tachogenerator", "correct": true}, {"id": "b", "text": "Feedback from control surface", "correct": false}, {"id": "c", "text": "Feedback from servo motor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The pitot head is fitted on the aircraft. The alignment of pitot head is carried out with', '[{"id": "a", "text": "an inclinometer", "correct": true}, {"id": "b", "text": "micrometer", "correct": false}, {"id": "c", "text": "spirit level", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stick shaker activates at a speed which is above the stalling speed by', '[{"id": "a", "text": "4%", "correct": false}, {"id": "b", "text": "7%", "correct": true}, {"id": "c", "text": "10.321%", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Versine signal is governed by', '[{"id": "a", "text": "roll", "correct": true}, {"id": "b", "text": "pitch", "correct": false}, {"id": "c", "text": "yaw", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Compass error remaining after all corrections are made is called', '[{"id": "a", "text": "apparent error", "correct": false}, {"id": "b", "text": "residual error", "correct": true}, {"id": "c", "text": "index error", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Instruments used on an aircraft are in some instances fitted with cover glasses whose surfaces are bloomed to reduce', '[{"id": "a", "text": "Parallax error", "correct": false}, {"id": "b", "text": "Surface reflection", "correct": true}, {"id": "c", "text": "Static to avoid dust attraction", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When more than one D.R. compass is fitted on an aircraft or where a D.R. compass serves as a standby to a remote reading compass only the master compass readings and adjustments carried out and remaining compasses are adjusted with', '[{"id": "a", "text": "master compass", "correct": false}, {"id": "b", "text": "all readings and adjustments for each compass should be made simultaneously on each heading", "correct": true}, {"id": "c", "text": "all readings and adjustments for each compass should be made at any one heading only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Standing waves in a Co-Axial feeder cable are proportional to', '[{"id": "a", "text": "length of the cable", "correct": false}, {"id": "b", "text": "transmitter power output", "correct": false}, {"id": "c", "text": "degree of mismatch between transmitter and antenna", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Dutch Roll affects', '[{"id": "a", "text": "yaw and roll simultaneously", "correct": true}, {"id": "b", "text": "pitch and yaw simultaneously", "correct": false}, {"id": "c", "text": "pitch and roll simultaneously", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When checking the altitude reporting of the transponder', '[{"id": "a", "text": "set the rad alt to 0 feet", "correct": false}, {"id": "b", "text": "set the barometric altimeter to 1013.25 mb", "correct": true}, {"id": "c", "text": "set the barometric altimeter to local pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Wing can spoilers be used?', '[{"id": "a", "text": "To assist the elevators", "correct": false}, {"id": "b", "text": "As ground spoilers on landing", "correct": true}, {"id": "c", "text": "To assist the respective down going aileron in a turn", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Direction of normal flight is changed by the pilot by applying pressure', '[{"id": "a", "text": "to the rudder pedals", "correct": false}, {"id": "b", "text": "to the control column", "correct": false}, {"id": "c", "text": "to the control wheel", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A Doppler VOR station`s transmissions', '[{"id": "a", "text": "can be received but not processed with a conventional VOR receiver", "correct": false}, {"id": "b", "text": "can not be received and processed with a conventional VOR receiver", "correct": false}, {"id": "c", "text": "can be received and processed with a conventional VOR receiver", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'on an Autoland coupled approach, a GPWS warning', '[{"id": "a", "text": "visual warning only", "correct": false}, {"id": "b", "text": "audio and Visual warning", "correct": true}, {"id": "c", "text": "would initiate a Go Around", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What frequency range does ACARS operate in?', '[{"id": "a", "text": "4-5 GHz", "correct": false}, {"id": "b", "text": "118-136 MHz", "correct": true}, {"id": "c", "text": "2-30 MHz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft receives a response from a DME station, 1236 microseconds after transmitting the interrogation. What is the slant range to the station?', '[{"id": "a", "text": "104 nautical miles", "correct": false}, {"id": "b", "text": "100 nautical miles", "correct": false}, {"id": "c", "text": "96 nautical miles", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'in an auto trim horizontal stabiliser, `low` speed mode is when', '[{"id": "a", "text": "flaps extended", "correct": true}, {"id": "b", "text": "landing gear up and locked", "correct": false}, {"id": "c", "text": "flaps are retracted", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Aircraft is north of VOR beacon, course is set to 90 degrees, RMI indicates', '[{"id": "a", "text": "0", "correct": false}, {"id": "b", "text": "180", "correct": true}, {"id": "c", "text": "90", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'MLS azimuth range is', '[{"id": "a", "text": "+/- 62", "correct": true}, {"id": "b", "text": "+/- 42", "correct": false}, {"id": "c", "text": "+/- 30", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'with no.1 h.f. system transmitting the interlock circuit', '[{"id": "a", "text": "does not allow no.2 to transmit or receive", "correct": false}, {"id": "b", "text": "allows no.2 h.f. to transmit and receive", "correct": false}, {"id": "c", "text": "allows no.2 h.f. to receive only", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Control loop gain with an autopilot is usually', '[{"id": "a", "text": "chosen as a compromise", "correct": true}, {"id": "b", "text": "100%", "correct": false}, {"id": "c", "text": "dependent on aircraft altitude", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With power applied to the autopilot but not engaged, the trim indicator will indicate', '[{"id": "a", "text": "the trim system is out of datum", "correct": false}, {"id": "b", "text": "that the gyro is out of the null and needs aligning", "correct": false}, {"id": "c", "text": "a standby electrical signal in the servo loop", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'at take off, if the flaps are lowered there is a', '[{"id": "a", "text": "large increase in lift and small increase in drag", "correct": true}, {"id": "b", "text": "small increase in lift and drag", "correct": false}, {"id": "c", "text": "large increase in lift and drag", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a large transport aircraft to check VSWR of a HF system with a long aerial feeder the VSWR meter has to be connected', '[{"id": "a", "text": "between the transmitter and the ATU (ATU end)", "correct": true}, {"id": "b", "text": "between the aerial and ATU", "correct": false}, {"id": "c", "text": "between the transmitter and the ATU (transmitter end)", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When the flaps are lowered', '[{"id": "a", "text": "there is no effect on the lift vector", "correct": false}, {"id": "b", "text": "the lift vector moves rearward", "correct": true}, {"id": "c", "text": "the lift vector moves forward", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A HUMS in a helicopter is', '[{"id": "a", "text": "a system which indicates a crack in the blade", "correct": false}, {"id": "b", "text": "a system which monitors time period of components in service and warns of a premature failure", "correct": false}, {"id": "c", "text": "a vibration analysis system", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Transformer coupling between ADI and Flight director is to protect', '[{"id": "a", "text": "both of the above", "correct": true}, {"id": "b", "text": "ADI", "correct": false}, {"id": "c", "text": "Flight director computer", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Co-axial transmission line of impedance 80 ohms is connected dipole of 120 ohms. While checking with ohm meter the reading will be', '[{"id": "a", "text": "more than 20 mega ohms", "correct": true}, {"id": "b", "text": "80 ohms", "correct": false}, {"id": "c", "text": "200 ohms", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'DME - how does receiver find the received pulse pairs are valid?', '[{"id": "a", "text": "Integrator", "correct": false}, {"id": "b", "text": "Blocking oscillator", "correct": false}, {"id": "c", "text": "Decoder", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In audio clipping', '[{"id": "a", "text": "there is no change in relative strength of vowels", "correct": false}, {"id": "b", "text": "vowels are attenuated relative to the remaining signal", "correct": true}, {"id": "c", "text": "vowels are strengthened relative to the remaining signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Anti cross-talk network for unwanted signals uses', '[{"id": "a", "text": "no attenuation but amplification", "correct": false}, {"id": "b", "text": "amplification first then attenuation", "correct": false}, {"id": "c", "text": "attenuation first then amplification", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Transformer coupling between an ADI and a flight director computer is', '[{"id": "a", "text": "to protect the FD computer in case of an HSI failure", "correct": false}, {"id": "b", "text": "to protect the FD computer in case of an ADI failure", "correct": false}, {"id": "c", "text": "to protect the ADI in event of a FD computer failure", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When an AM carrier is modulated, its bandwidth', '[{"id": "a", "text": "remains the same", "correct": false}, {"id": "b", "text": "decreases", "correct": false}, {"id": "c", "text": "increases", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A helicopter needs to re-trim', '[{"id": "a", "text": "indication is shown on the command bars of the attitude indicator", "correct": false}, {"id": "b", "text": "indication is shown on the command bars of the EHSI", "correct": false}, {"id": "c", "text": "indication is shown on the API", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the inductance in a parallel tuned circuit is increased in value, the resonant frequency', '[{"id": "a", "text": "increases", "correct": false}, {"id": "b", "text": "decreases", "correct": true}, {"id": "c", "text": "remains the same", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Flight director on G/S capture, the pitch integration is', '[{"id": "a", "text": "to maintain GS signal", "correct": true}, {"id": "b", "text": "to increase GS signal", "correct": false}, {"id": "c", "text": "to decrease GS signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Flight director on VOR, course error wash out signal is lost, following the FD commands. Aircraft will', '[{"id": "a", "text": "follow the course with scalloping or bracketing", "correct": true}, {"id": "b", "text": "stay parallel to course", "correct": false}, {"id": "c", "text": "stay on centre of course", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'WX radar display the time base is', '[{"id": "a", "text": "rectangular wave form", "correct": false}, {"id": "b", "text": "trapezoidal wave form", "correct": false}, {"id": "c", "text": "saw tooth wave form", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Speed control on an emergency hydraulic driven generator is via the', '[{"id": "a", "text": "swash plate", "correct": true}, {"id": "b", "text": "CSD", "correct": false}, {"id": "c", "text": "IDG", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The term `circling current` refers to', '[{"id": "a", "text": "DC generators", "correct": false}, {"id": "b", "text": "AC and DC Generators", "correct": false}, {"id": "c", "text": "AC generators", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A DGPS system installed on an aircraft requires', '[{"id": "a", "text": "1 ground station and 6 satellites", "correct": false}, {"id": "b", "text": "2 ground stations and 4 satellites", "correct": false}, {"id": "c", "text": "1 ground station and 4 satellites", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which would you use to test an aircraft transponder altitude reporting system?', '[{"id": "a", "text": "Check the altitude code with the correct alt/code table", "correct": false}, {"id": "b", "text": "Transfer the code displayed by the ATC-600 into binary", "correct": false}, {"id": "c", "text": "Read the altitude directly from ATC-600 panel", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mode C response is', '[{"id": "a", "text": "8 microseconds", "correct": false}, {"id": "b", "text": "12 microseconds", "correct": false}, {"id": "c", "text": "21microseconds", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'FMC mode that can be selected through the CDU is', '[{"id": "a", "text": "CRZ", "correct": true}, {"id": "b", "text": "LNAV", "correct": false}, {"id": "c", "text": "DME Freq", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Cat IIIB landing, up to what phase is LOC signal used?', '[{"id": "a", "text": "Touchdown", "correct": false}, {"id": "b", "text": "Flare", "correct": false}, {"id": "c", "text": "Roll out", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ADF operates within which frequencies?', '[{"id": "a", "text": "32 KHz - 64 KHz", "correct": false}, {"id": "b", "text": "118 MHz - 132 MHz", "correct": false}, {"id": "c", "text": "200 KHz - 1000 KHz", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A `q` feel system supplies', '[{"id": "a", "text": "control movement effort relief", "correct": false}, {"id": "b", "text": "the pilot with ever increasing awareness of speed", "correct": true}, {"id": "c", "text": "aerodynamic damping", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the torque were increased on a vertical gyro, what would happen to the precession?', '[{"id": "a", "text": "Decrease", "correct": false}, {"id": "b", "text": "Increase", "correct": true}, {"id": "c", "text": "Remain unaffected", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The result of the equation (Dev E - Dev W)/2 is known as', '[{"id": "a", "text": "Coefficient C", "correct": false}, {"id": "b", "text": "Coefficient A", "correct": false}, {"id": "c", "text": "Coefficient B", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which is used for compass damping fluid compensation?', '[{"id": "a", "text": "Piston and oil", "correct": false}, {"id": "b", "text": "No damping due to alcohol low temperature co-efficient", "correct": false}, {"id": "c", "text": "Bellows or diaphragm", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On a Ground Power unit which pins are allocated for interlock circuit?', '[{"id": "a", "text": "E and F", "correct": true}, {"id": "b", "text": "B and C", "correct": false}, {"id": "c", "text": "A and B", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What does a vibration type sensor measure?', '[{"id": "a", "text": "Direction of flexing", "correct": false}, {"id": "b", "text": "Frequency of deflections", "correct": true}, {"id": "c", "text": "Maximum deflection", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which signal would be integrated to get onto Localiser centreline?', '[{"id": "a", "text": "Radio deviation", "correct": true}, {"id": "b", "text": "Course error", "correct": false}, {"id": "c", "text": "Heading error", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What effect does lowering flaps for takeoff have?', '[{"id": "a", "text": "Reduces landing speeds only", "correct": false}, {"id": "b", "text": "Reduces takeoff speeds only", "correct": true}, {"id": "c", "text": "Reduces takeoff and landing speeds", "correct": false}]'::jsonb, '{B2}'),
