    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The instantaneous VSI is designed to', '[{"id": "a", "text": "improve the VSI output during acceleration greater than 1g", "correct": false}, {"id": "b", "text": "use an accelerometer to give a rate of climb/descent", "correct": false}, {"id": "c", "text": "overcome the inherent lag by utilising an accelerometer", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stand off errors on localiser approach are washed out by', '[{"id": "a", "text": "integrating course error signals", "correct": false}, {"id": "b", "text": "integrating deviation signals", "correct": true}, {"id": "c", "text": "differentiating deviation signals", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Aileron to rudder crossfeed is applied in autopilot systems to', '[{"id": "a", "text": "prevents aircraft yawing in the opposite direction to the turn", "correct": true}, {"id": "b", "text": "prevents slip and skid in yaw", "correct": false}, {"id": "c", "text": "assist the aircraft back to datum after disturbance in yaw", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The neutral shift sensor ensures that', '[{"id": "a", "text": "after an auto trim, the stabiliser is moved to align with the elevator", "correct": false}, {"id": "b", "text": "after a mach trim, the stabiliser is moved to align with the elevator", "correct": false}, {"id": "c", "text": "after an auto trim, the elevator is moved to align with the stabiliser", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When paralleling two AC generators', '[{"id": "a", "text": "they do not need to be in phase", "correct": false}, {"id": "b", "text": "it is important that they are in phase, and can be brought on in either ABC or CBA", "correct": false}, {"id": "c", "text": "it is important that they are in phase, and should be brought on in sequence ABC", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On AC ground power the interlock system is operated by pins', '[{"id": "a", "text": "c and d", "correct": false}, {"id": "b", "text": "e and f", "correct": true}, {"id": "c", "text": "a and b", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Wing steady light must be visible through', '[{"id": "a", "text": "180 degrees", "correct": false}, {"id": "b", "text": "110 degrees", "correct": true}, {"id": "c", "text": "70 degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When removing the load from a current transformer', '[{"id": "a", "text": "leave the terminals open", "correct": false}, {"id": "b", "text": "place a resistor across each terminal", "correct": false}, {"id": "c", "text": "short the terminals", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Distilled or demineralised water would be added to an alkaline battery', '[{"id": "a", "text": "when the battery is fully charged", "correct": true}, {"id": "b", "text": "in the charging room only", "correct": false}, {"id": "c", "text": "in the aircraft", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A differential relay in a twin generator system will cause', '[{"id": "a", "text": "the generator voltages are nearly equal before they are paralleled", "correct": true}, {"id": "b", "text": "one generator always comes on line before the other", "correct": false}, {"id": "c", "text": "only one generator can supply a bus bar at a time", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The purpose of a force trim release system in an helicopter is to permit the appropriate cyclic actuator to be over powered', '[{"id": "a", "text": "pilot to move the collective to obtain a power change", "correct": false}, {"id": "b", "text": "pilot to move the cyclic stick to obtain desired new attitude without having to maintain the opposing", "correct": true}, {"id": "c", "text": "of the artificial feel system forces", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How are spoilers normally operated?', '[{"id": "a", "text": "Electrical motors", "correct": false}, {"id": "b", "text": "Air pistons", "correct": false}, {"id": "c", "text": "Hydraulic actuator", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With on-board maintenance (OBM) systems, the purpose of central maintenance function (CMF) is to', '[{"id": "a", "text": "provides details of defect action", "correct": false}, {"id": "b", "text": "transmits to the CMC", "correct": false}, {"id": "c", "text": "log relevant maintenance data", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stall warning will be given', '[{"id": "a", "text": "at stall", "correct": false}, {"id": "b", "text": "after stall", "correct": false}, {"id": "c", "text": "before stall", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A series actuator in a helicopter autopilot system has', '[{"id": "a", "text": "10% authority", "correct": true}, {"id": "b", "text": "50% authority", "correct": false}, {"id": "c", "text": "full authority", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A triplex system loses one channel', '[{"id": "a", "text": "pilot must make a full manual approach and land", "correct": false}, {"id": "b", "text": "pilot can use auto approach", "correct": false}, {"id": "c", "text": "pilot can continue with autoland", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Glideslope deviation signals are', '[{"id": "a", "text": "DC positive going only", "correct": false}, {"id": "b", "text": "AC phase sensitive", "correct": false}, {"id": "c", "text": "DC polarity sensitive", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A yaw damper will apply rudder proportional to', '[{"id": "a", "text": "rate of yaw", "correct": true}, {"id": "b", "text": "attitude of aircraft", "correct": false}, {"id": "c", "text": "amount of aircraft disturbance", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a turn, wing spoilers may be deployed', '[{"id": "a", "text": "to assist the up going aileron", "correct": true}, {"id": "b", "text": "in unison with both the up going and down going ailerons", "correct": false}, {"id": "c", "text": "to act as an airbrake, interacting with the ailerons", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When the aircraft nose yaws to the left, the yaw damper will apply corrective rudder to', '[{"id": "a", "text": "the left with some aileron assistance", "correct": false}, {"id": "b", "text": "the left", "correct": false}, {"id": "c", "text": "the right", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), '`Q` feel for the stabiliser requires', '[{"id": "a", "text": "pitot and static", "correct": true}, {"id": "b", "text": "static only", "correct": false}, {"id": "c", "text": "pitot only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On localiser approach the radio deviation signal is lost', '[{"id": "a", "text": "aircraft flies heading with increasing drift angle", "correct": false}, {"id": "b", "text": "aircraft flies off centre line on pre-set heading", "correct": true}, {"id": "c", "text": "the aircraft flies in a circle", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The respective band widths for a radar IF amplifier and video amplifier should be for good pulse shape are', '[{"id": "a", "text": "wide and wide", "correct": true}, {"id": "b", "text": "narrow and wide", "correct": false}, {"id": "c", "text": "wide and narrow", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The pseudo-random code used by all civilian GPS users is', '[{"id": "a", "text": "the c/a code", "correct": true}, {"id": "b", "text": "the p code", "correct": false}, {"id": "c", "text": "the y code", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Fibre glass parts are protected from lightning strikes and dangerous voltages by', '[{"id": "a", "text": "earth primary conductors", "correct": false}, {"id": "b", "text": "conductive paint", "correct": true}, {"id": "c", "text": "non conductive paint", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The bearing of a NDB measured by ADF is 060 degrees relative to aircraft heading of 030 degrees. The RMI pointer indicates', '[{"id": "a", "text": "60 degrees", "correct": false}, {"id": "b", "text": "90 degrees", "correct": true}, {"id": "c", "text": "30 degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The maximum azimuth coverage by a MLS facility is', '[{"id": "a", "text": "+/-60 degrees", "correct": true}, {"id": "b", "text": "+/-40 degrees", "correct": false}, {"id": "c", "text": "+/- 35 degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Microwave landing systems are modulated with', '[{"id": "a", "text": "Manchester code", "correct": true}, {"id": "b", "text": "phase drift keying", "correct": false}, {"id": "c", "text": "FM", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Emergency electronic equipment for the cabin is referred to in', '[{"id": "a", "text": "maintenance manual", "correct": false}, {"id": "b", "text": "JAR OPS subpart M", "correct": true}, {"id": "c", "text": "BCARs", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Carbon microphones require', '[{"id": "a", "text": "no supply", "correct": false}, {"id": "b", "text": "AC supply", "correct": false}, {"id": "c", "text": "DC supply", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Deviation from the HSI lubber line is known as', '[{"id": "a", "text": "true A", "correct": false}, {"id": "b", "text": "real A", "correct": false}, {"id": "c", "text": "apparent A", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Electronic stab trim switches are found on the', '[{"id": "a", "text": "behind thrust levers", "correct": false}, {"id": "b", "text": "flight control panel", "correct": false}, {"id": "c", "text": "control column", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'on power up, the IRS obtains position', '[{"id": "a", "text": "latitude and longitude from previous position", "correct": true}, {"id": "b", "text": "longitude from previous position", "correct": false}, {"id": "c", "text": "latitude from previous position", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Krueger flaps make up part of the', '[{"id": "a", "text": "wing lower surface leading edge", "correct": true}, {"id": "b", "text": "wing lower surface trailing edge", "correct": false}, {"id": "c", "text": "wing upper surface leading edge", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Medium vibration of 4 to 6 times per revolution is experienced on a helicopter. The primary control method is', '[{"id": "a", "text": "inspect main rotor head and main drive shaft", "correct": false}, {"id": "b", "text": "design of engine and gearbox supports", "correct": true}, {"id": "c", "text": "inspect loose fixtures and fittings", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPS sends L1 and L2. What is on L1?', '[{"id": "a", "text": "P code only", "correct": false}, {"id": "b", "text": "c/a code and P code", "correct": true}, {"id": "c", "text": "c/a code only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is VHF comm range at 9000 feet?', '[{"id": "a", "text": "130 nm", "correct": false}, {"id": "b", "text": "120 nm", "correct": true}, {"id": "c", "text": "110 nm", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'DME reply pulses are 63MHZ', '[{"id": "a", "text": "higher or lower", "correct": true}, {"id": "b", "text": "lower", "correct": false}, {"id": "c", "text": "higher", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Flight director incompatible modes are', '[{"id": "a", "text": "VOR and altitude hold", "correct": false}, {"id": "b", "text": "heading and altitude hold", "correct": false}, {"id": "c", "text": "VOR and glideslope", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With a bonding meter', '[{"id": "a", "text": "it does not matter which lead goes where", "correct": false}, {"id": "b", "text": "the short lead to the aircraft airframe and long lead to the item", "correct": false}, {"id": "c", "text": "the long lead is attached to the aircraft air frame and short lead to item", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Back beam is captured', '[{"id": "a", "text": "by manually selecting the L NAV mode", "correct": false}, {"id": "b", "text": "this automatically trips the L NAV mode", "correct": false}, {"id": "c", "text": "by manually selecting the back beam mode", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'in air speed hold mode, a down displacement of the flight director pitch command bar signifies', '[{"id": "a", "text": "height decrease", "correct": false}, {"id": "b", "text": "speed decrease", "correct": true}, {"id": "c", "text": "speed increase", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The advancing blade of a helicopter is the one moving', '[{"id": "a", "text": "one moving forward into relative airflow", "correct": true}, {"id": "b", "text": "highest blade", "correct": false}, {"id": "c", "text": "one moving in direction of relative air flow", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Fluorescent tubes for the cabin lighting are powered from', '[{"id": "a", "text": "high voltage produced by transformer ballast units", "correct": true}, {"id": "b", "text": "200 volts from ac bus", "correct": false}, {"id": "c", "text": "115 volts from ac bus", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'in a superhet receiver, the advantage of an RF amplifier is', '[{"id": "a", "text": "it couples noise factors", "correct": false}, {"id": "b", "text": "it improves signal to noise ratio", "correct": true}, {"id": "c", "text": "it amplifies output stages", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Radio switches are normally', '[{"id": "a", "text": "latched on R/T, latched on I/C", "correct": false}, {"id": "b", "text": "latched on R/T, sprung on I/C", "correct": false}, {"id": "c", "text": "sprung on R/T, latched on I/C", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPS frequency is', '[{"id": "a", "text": "1525 MHz", "correct": false}, {"id": "b", "text": "1575 MHz", "correct": true}, {"id": "c", "text": "1575 GHz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPS has', '[{"id": "a", "text": "27 satellites, 3 orbits of 9", "correct": false}, {"id": "b", "text": "24 satellites, 4 orbits of 6", "correct": false}, {"id": "c", "text": "24 satellites, 6 orbits of 4", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The crew select DH on', '[{"id": "a", "text": "the rad alt display", "correct": true}, {"id": "b", "text": "the DH annunciator panel", "correct": false}, {"id": "c", "text": "the altimeter", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When substituting the radio altimeter antenna cables, you should consider', '[{"id": "a", "text": "the diameter of cables", "correct": false}, {"id": "b", "text": "the speed of propagation of rad alt signal", "correct": true}, {"id": "c", "text": "power requirements", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The audio select panel allows the crew to', '[{"id": "a", "text": "receive on one channel, transmit on multiple others", "correct": false}, {"id": "b", "text": "transmit on one channel, listen on multiple others", "correct": true}, {"id": "c", "text": "transmit on one channel, listen on one", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The ground run monitor presents information', '[{"id": "a", "text": "angle of crosstrack on ground", "correct": false}, {"id": "b", "text": "duration of ground run", "correct": false}, {"id": "c", "text": "of distance to go and ground speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A mode C transponder', '[{"id": "a", "text": "can be used for TCAS on ILS approach only", "correct": false}, {"id": "b", "text": "cannot be used for TCAS", "correct": false}, {"id": "c", "text": "can be used for TCAS", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Artificial feel is gained by using a', '[{"id": "a", "text": "`feel` generator", "correct": true}, {"id": "b", "text": "spring bias unit", "correct": false}, {"id": "c", "text": "hydraulic damper", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Tracking is carried out to_____________the MRB tip path', '[{"id": "a", "text": "align", "correct": true}, {"id": "b", "text": "restore", "correct": false}, {"id": "c", "text": "balance", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The rotor cone is formed by', '[{"id": "a", "text": "centrifugal force only", "correct": false}, {"id": "b", "text": "centrifugal force and lift", "correct": true}, {"id": "c", "text": "blade alignment", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mode S transponders transmits a binary code of', '[{"id": "a", "text": "24bits", "correct": true}, {"id": "b", "text": "64bits", "correct": false}, {"id": "c", "text": "12bits", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The best design of a MRB is where the C of P', '[{"id": "a", "text": "is insignificant", "correct": false}, {"id": "b", "text": "moves freely along the length of the blade", "correct": false}, {"id": "c", "text": "does not move", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'DME transponder transmits on receipt', '[{"id": "a", "text": "of a pair of pulses separated by 12 microseconds", "correct": true}, {"id": "b", "text": "of pilot input command request", "correct": false}, {"id": "c", "text": "of any interrogation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What controls are used in response to PVD display?', '[{"id": "a", "text": "Control wheel", "correct": false}, {"id": "b", "text": "PVD control unit", "correct": false}, {"id": "c", "text": "Nose wheel steering or rudder pedals", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'on a helicopter, what is vortex ring state?', '[{"id": "a", "text": "Tip vortex build-up during hover", "correct": true}, {"id": "b", "text": "Ground vortex interference when hovering close to the ground", "correct": false}, {"id": "c", "text": "Tip vortex interference at high forward speed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What does the Radar contour button do?', '[{"id": "a", "text": "Alter the video amplifier", "correct": true}, {"id": "b", "text": "Alter the transmitter power", "correct": false}, {"id": "c", "text": "Alter the beam shape", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A radar response takes 329 micro seconds how far away is the target?', '[{"id": "a", "text": "40 miles", "correct": false}, {"id": "b", "text": "25 miles", "correct": true}, {"id": "c", "text": "12 miles", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If a VOR RMI indicates 000 degrees and the course selected is 000 degrees what will the TO/FROM indicator indicate?', '[{"id": "a", "text": "Neither", "correct": false}, {"id": "b", "text": "TO", "correct": true}, {"id": "c", "text": "FROM", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If you carry out a VSWR check of a SSB HF system what should you do with the control switch? Select it to', '[{"id": "a", "text": "either USB or LSB", "correct": false}, {"id": "b", "text": "AM", "correct": true}, {"id": "c", "text": "OFF", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is a versine signal attenuated with?', '[{"id": "a", "text": "Decrease in altitude", "correct": false}, {"id": "b", "text": "Increase in altitude", "correct": false}, {"id": "c", "text": "Increase in airspeed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Why is a wire HF antenna covered in polythene?', '[{"id": "a", "text": "To provide lightning protection", "correct": false}, {"id": "b", "text": "To prevent precipitation static", "correct": true}, {"id": "c", "text": "To prevent corrosion", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A spring balance control system you', '[{"id": "a", "text": "cannot move the control surface on the ground", "correct": false}, {"id": "b", "text": "can move the control surface only by moving the tab", "correct": false}, {"id": "c", "text": "can move the control surface on the ground", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Once the G/S has been captured what other pitch modes are available?', '[{"id": "a", "text": "All are continuously available", "correct": false}, {"id": "b", "text": "Only when the aircraft is above the glideslope beam", "correct": false}, {"id": "c", "text": "No other pitch modes are available", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which of the following modes does a autopilot go through in correct sequence?', '[{"id": "a", "text": "Rollout, attitude, flare", "correct": false}, {"id": "b", "text": "Attitude, flare, rollout", "correct": true}, {"id": "c", "text": "Flare, attitude, rollout", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On an ILS approach what will cause the aircraft to fly onto the beam?', '[{"id": "a", "text": "Course deviation", "correct": false}, {"id": "b", "text": "Glideslope deviation", "correct": false}, {"id": "c", "text": "Radio deviation", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A helicopter autopilot uses', '[{"id": "a", "text": "barometric altitude for both height and altitude hold", "correct": false}, {"id": "b", "text": "barometric altitude for height hold and radio altitude for altitude hold", "correct": false}, {"id": "c", "text": "radio altitude for height hold and barometric altitude for altitude hold", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft with autoland is fitted with a CMC', '[{"id": "a", "text": "all memory is erased when aircraft lands", "correct": false}, {"id": "b", "text": "records all faults in non-volatile memory", "correct": true}, {"id": "c", "text": "records all faults in volatile memory", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When will a mode C interrogation be ignored?', '[{"id": "a", "text": "If P2 is before P1", "correct": false}, {"id": "b", "text": "When the P2 pulse is antiphase to P1", "correct": false}, {"id": "c", "text": "When the P2 pulse is higher amplitude to P1", "correct": true}]'::jsonb, '{B2}'),
