    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When all three leads of a bonding tester are connected together the output reading is', '[{"id": "a", "text": "centre scale", "correct": false}, {"id": "b", "text": "full scale deflection", "correct": false}, {"id": "c", "text": "zero", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the power supply to cabin flow tubes?', '[{"id": "a", "text": "High voltage stepped up", "correct": true}, {"id": "b", "text": "200v ac", "correct": false}, {"id": "c", "text": "115v ac", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a fully fly by wire system if the rudder becomes disconnected', '[{"id": "a", "text": "it is centralized by the airflow", "correct": false}, {"id": "b", "text": "its control is maintained by electric trim", "correct": false}, {"id": "c", "text": "it is centralized by a spring", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'As the rotor head is tilted to travel forward what happens to the reward travelling blades pitch angle?', '[{"id": "a", "text": "No change", "correct": false}, {"id": "b", "text": "Increases", "correct": true}, {"id": "c", "text": "Decreases", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A CSD is monitored for', '[{"id": "a", "text": "high temp and high oil pressure", "correct": false}, {"id": "b", "text": "high temp and low oil pressure", "correct": true}, {"id": "c", "text": "low temp and high oil pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'During flare mode autothrottle will', '[{"id": "a", "text": "select reverse thrust", "correct": false}, {"id": "b", "text": "retard throttles to idle", "correct": true}, {"id": "c", "text": "disconnect autothrottle", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The doppler VOR beacon reference signal', '[{"id": "a", "text": "frequency modulates the sub carrier frequency", "correct": false}, {"id": "b", "text": "amplitude modulates the sub carrier frequency", "correct": false}, {"id": "c", "text": "amplitude modulates the carrier frequency", "correct": true}]'::jsonb, '{B2}'),
