    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The applied pressure to an ASI varies with the', '[{"id": "a", "text": "cube root of the speed", "correct": false}, {"id": "b", "text": "square root of the speed", "correct": false}, {"id": "c", "text": "square of the speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How many bits make up the mode "S" address', '[{"id": "a", "text": "12", "correct": false}, {"id": "b", "text": "24", "correct": true}, {"id": "c", "text": "36", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPWS mode 1 is excessive', '[{"id": "a", "text": "rate of ascent", "correct": false}, {"id": "b", "text": "rate of descent", "correct": true}, {"id": "c", "text": "terrain closure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Magnetic variation is the difference in angle between', '[{"id": "a", "text": "the compass north and magnetic north", "correct": false}, {"id": "b", "text": "magnetic heading and aircraft heading", "correct": false}, {"id": "c", "text": "true north and magnetic north", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A fuel flow system can be adjusted for', '[{"id": "a", "text": "minimum flow rate", "correct": true}, {"id": "b", "text": "cannot be adjusted", "correct": false}, {"id": "c", "text": "maximum flow rate", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A unit with two springs and a mass pick off is', '[{"id": "a", "text": "a tachogenerator", "correct": false}, {"id": "b", "text": "a gyroscope", "correct": false}, {"id": "c", "text": "an accelerometer", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The units of vibration are measured in', '[{"id": "a", "text": "relative amplitude", "correct": true}, {"id": "b", "text": "phons", "correct": false}, {"id": "c", "text": "decibels", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When the VOR ref and Vari phase are in phase quadrature, the aircraft is at the', '[{"id": "a", "text": "275 degree radial", "correct": false}, {"id": "b", "text": "090 degree radial", "correct": true}, {"id": "c", "text": "180 degree radial", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When an aircraft is at a height of 9500ft and the QNH is 500 ft what is the distance that VHF Com cover?', '[{"id": "a", "text": "140 nm", "correct": false}, {"id": "b", "text": "120 nm", "correct": true}, {"id": "c", "text": "100 nm", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Emergency electronic equipment requirement will be found in', '[{"id": "a", "text": "JAR OPS", "correct": true}, {"id": "b", "text": "CAAIPs", "correct": false}, {"id": "c", "text": "Maintenance Manual", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When working on a hydraulic operated flight control it is sensible to', '[{"id": "a", "text": "remove/disconnect electrical power", "correct": false}, {"id": "b", "text": "pull the appropriate CB", "correct": false}, {"id": "c", "text": "remove/disconnect hydraulic power", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The electrical A/H has a movement of', '[{"id": "a", "text": "360 in roll and 85 in pitch", "correct": true}, {"id": "b", "text": "360 in roll and 110 in pitch", "correct": false}, {"id": "c", "text": "85 degree in pitch and roll", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a modern aircraft a BITE is carried out', '[{"id": "a", "text": "only in the air", "correct": false}, {"id": "b", "text": "continuously when the systems are working", "correct": true}, {"id": "c", "text": "on the ground only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The international emergency frequency used in VHF Comms is', '[{"id": "a", "text": "118.00", "correct": false}, {"id": "b", "text": "121.5", "correct": true}, {"id": "c", "text": "131.55", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A rain fall of 5mm/hr is indicated in the WXR by a', '[{"id": "a", "text": "red colour", "correct": false}, {"id": "b", "text": "yellow colour", "correct": true}, {"id": "c", "text": "green colour", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An autopilot interlock circuit is to', '[{"id": "a", "text": "both a & b", "correct": true}, {"id": "b", "text": "disconnect the system if a fault appears", "correct": false}, {"id": "c", "text": "prevent the system engagement if a fault exists", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Loss of an electrolyte in a battery is due to', '[{"id": "a", "text": "excessive charging voltage", "correct": true}, {"id": "b", "text": "excessive charging current", "correct": false}, {"id": "c", "text": "insufficient charging current", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'FADEC system gets its power supply from', '[{"id": "a", "text": "emergency Batt bus", "correct": false}, {"id": "b", "text": "channel A and B from separate windings of a dedicated Generator", "correct": true}, {"id": "c", "text": "channel A and B from the same windings of a dedicated Generator", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stall warning will be given at speeds', '[{"id": "a", "text": "at the actual stall speed", "correct": false}, {"id": "b", "text": "that are lower than stall speed", "correct": false}, {"id": "c", "text": "that are higher than stall speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'when a helicopter lands how does the pilot signal to the ground staff that it is safe to approach the aircraft?', '[{"id": "a", "text": "Flashing the landing light", "correct": false}, {"id": "b", "text": "Turning off the anti-collision lights", "correct": true}, {"id": "c", "text": "Turning on and off the NAV lights", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Circulating currents is caused by an unbalanced', '[{"id": "a", "text": "AC & DC generators", "correct": false}, {"id": "b", "text": "AC generators", "correct": true}, {"id": "c", "text": "DC generators", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A device used do dump lift from an aircraft is the', '[{"id": "a", "text": "leading edge flaps", "correct": false}, {"id": "b", "text": "trailing edge flaps", "correct": false}, {"id": "c", "text": "spoiler", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The quadrantal error in ADF is maximum at a heading of', '[{"id": "a", "text": "090", "correct": false}, {"id": "b", "text": "045", "correct": true}, {"id": "c", "text": "000", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When an aircraft is aligned for a compass swing check to be carried out it will be aligned with an error of plus or minus', '[{"id": "a", "text": "5 degree", "correct": false}, {"id": "b", "text": "3 degree", "correct": false}, {"id": "c", "text": "1 degree", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'TCAS transmits and receives on a frequency of', '[{"id": "a", "text": "1090 MHz", "correct": false}, {"id": "b", "text": "1090mhz and 1030mhz respectively", "correct": false}, {"id": "c", "text": "1030 MHz and 1090mhz respectively", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If a drain trap in a pitot static system is removed but nothing was found', '[{"id": "a", "text": "a leak test is never required", "correct": false}, {"id": "b", "text": "a leak test must be carried out even if nothing found", "correct": true}, {"id": "c", "text": "no leak test is required unless the drain trap contains water", "correct": false}]'::jsonb, '{B2}'),
