    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The Ground Proximity Warning Computer in mode 4 would use which inputs to issue a warning?', '[{"id": "a", "text": "A low range altimeter and GPS", "correct": false}, {"id": "b", "text": "A low range altimeter and configuration of aircraft", "correct": true}, {"id": "c", "text": "A low range altimeter and rate of change of low range altimeter", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With a trailing edge flap being lowered, due to rising gusts what will happen to the angle of attack?', '[{"id": "a", "text": "Stay the same", "correct": false}, {"id": "b", "text": "Tend to decrease", "correct": false}, {"id": "c", "text": "Tend to increase", "correct": true}]'::jsonb, '{B2}'),
