    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Other than spoilers, where are speed brakes located?', '[{"id": "a", "text": "Either side of the Fuselage", "correct": true}, {"id": "b", "text": "Under the Fuselage", "correct": false}, {"id": "c", "text": "On the wing", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The VHF aerial resistance and transmission line resistance is', '[{"id": "a", "text": "20 and 50 ohms respectively", "correct": false}, {"id": "b", "text": "20 ohms", "correct": false}, {"id": "c", "text": "50 ohms", "correct": true}]'::jsonb, '{B2}'),
