    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If a fault is detected during an autoland approach the system will totally disconnect if it is a', '[{"id": "a", "text": "Simplex system", "correct": false}, {"id": "b", "text": "Duplex system", "correct": true}, {"id": "c", "text": "Triplex system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What should be done to a transformer secondary connections which are open circuit?', '[{"id": "a", "text": "Leave the terminals open circuit", "correct": true}, {"id": "b", "text": "Put a set resistance across the terminals", "correct": false}, {"id": "c", "text": "Short the terminals together", "correct": false}]'::jsonb, '{B2}'),
