    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Sparking in a generator would be caused by', '[{"id": "a", "text": "brushes on the Magnetic Neutral Axis", "correct": false}, {"id": "b", "text": "bedding of brushes", "correct": false}, {"id": "c", "text": "low spring tension", "correct": true}]'::jsonb, '{B2}'),
