    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The total static resistance along the length of an aircraft is', '[{"id": "a", "text": "1M - 100,000 ohms", "correct": false}, {"id": "b", "text": "1 ohms", "correct": false}, {"id": "c", "text": "50 milliohms", "correct": true}]'::jsonb, '{B2}'),
