    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'CAT-3b allows', '[{"id": "a", "text": "approach land and runway guidance with taxing visibility in the order of 50 meters", "correct": false}, {"id": "b", "text": "approach land and RVR in the order of 50 meters", "correct": true}, {"id": "c", "text": "approach land and runway guidance with zero DH and RVR", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The definition of fail operational is the ability of a system to', '[{"id": "a", "text": "disconnect but leave the aircraft out of trim", "correct": false}, {"id": "b", "text": "continue to control after any first fault", "correct": true}, {"id": "c", "text": "disconnect and leave the aircraft in trim", "correct": false}]'::jsonb, '{B2}'),
