    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The two parameters used for category classification are', '[{"id": "a", "text": "decision height and runway visual range", "correct": true}, {"id": "b", "text": "localiser and glideslope", "correct": false}, {"id": "c", "text": "radio height/runway visual range", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A triplex system loses one channel, the system becomes a', '[{"id": "a", "text": "dual-dual system", "correct": false}, {"id": "b", "text": "duplex system", "correct": true}, {"id": "c", "text": "simplex system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A fail passive system in the event of failure will', '[{"id": "a", "text": "ensure the aircraft can still land automatically", "correct": false}, {"id": "b", "text": "produce no significant out of trim condition", "correct": true}, {"id": "c", "text": "produce a significant out of trim condition", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The flare manoeuvre may be controlled by signals from', '[{"id": "a", "text": "the localiser receiver", "correct": false}, {"id": "b", "text": "the glide slope receiver", "correct": false}, {"id": "c", "text": "radio altimeter", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A triplex system looses one channel, the system is now,', '[{"id": "a", "text": "fail redundant", "correct": false}, {"id": "b", "text": "fail operational", "correct": false}, {"id": "c", "text": "fail passive", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Automatic steering of the aircraft after touch down is affected by', '[{"id": "a", "text": "the airfield marker beacon", "correct": false}, {"id": "b", "text": "the runway localiser", "correct": true}, {"id": "c", "text": "the area navigation system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'on touchdown, auto pilot', '[{"id": "a", "text": "disconnects after a short time", "correct": true}, {"id": "b", "text": "drives the throttles forward", "correct": false}, {"id": "c", "text": "remains engaged ready for G/A", "correct": false}]'::jsonb, '{B2}'),
