    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The following modes may be retained when overshoot has been initiated after the selection of autoland', '[{"id": "a", "text": "IAS and steering or heading", "correct": true}, {"id": "b", "text": "IAS and glide slope", "correct": false}, {"id": "c", "text": "ILS localiser an IAS", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If go-around has been initiated after autoland has been selected, the aeroplane will', '[{"id": "a", "text": "increase speed and rotate nose up", "correct": true}, {"id": "b", "text": "rotate nose up", "correct": false}, {"id": "c", "text": "increase speed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Overshoot or go-around mode can be initiated', '[{"id": "a", "text": "at any time", "correct": true}, {"id": "b", "text": "at any time after autoland has been engaged", "correct": false}, {"id": "c", "text": "only when the autopilot is engaged", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The overshoot or go around mode is initiated', '[{"id": "a", "text": "by pushing the throttles forward to maximum", "correct": false}, {"id": "b", "text": "by a selector on the throttle control panel", "correct": true}, {"id": "c", "text": "automatically", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The aeroplanes autopilot is programmed to leave the glide slope at', '[{"id": "a", "text": "start of flare phase", "correct": true}, {"id": "b", "text": "the decrab phase", "correct": false}, {"id": "c", "text": "300 ft", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'For an aeroplane to be certified for automatic landing an autothrottle system is', '[{"id": "a", "text": "dependent upon the operation of the aeroplane at slow speed", "correct": false}, {"id": "b", "text": "mandatory", "correct": false}, {"id": "c", "text": "a matter of choice for the operator", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Before an aeroplane is able to make an automatic landing the', '[{"id": "a", "text": "ILS system must be working", "correct": false}, {"id": "b", "text": "ground radio aids must be at CAT III", "correct": true}, {"id": "c", "text": "ground radio aids must be at least CAT II", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The average risk of autoland should not contribute a rate of fatal accidents per landing greater than', '[{"id": "a", "text": "1 x 10-8", "correct": false}, {"id": "b", "text": "1 x 10-6", "correct": false}, {"id": "c", "text": "1 x 10-7", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The facility performance ILS intersect height is the point', '[{"id": "a", "text": "where the aeroplanes first receives both the localiser and glide path signals", "correct": false}, {"id": "b", "text": "the localiser and glide path signals cross each other", "correct": true}, {"id": "c", "text": "where the aeroplane receives the first glide path signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A category 11 facility performance ILS has an intercept height of', '[{"id": "a", "text": "0 m", "correct": false}, {"id": "b", "text": "60 m", "correct": false}, {"id": "c", "text": "15 m", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The ICAO weather category 3A is', '[{"id": "a", "text": "operation down to and along the surface of the runway with RVR of 200m", "correct": true}, {"id": "b", "text": "operation down to 60 m and 800 m", "correct": false}, {"id": "c", "text": "operation down to and along the surface of the runway without external reference", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The wheel height at which the approach path has been visually assessed as satisfactory to continue the approach to a landing is know as the', '[{"id": "a", "text": "alert height", "correct": false}, {"id": "b", "text": "intercept height", "correct": false}, {"id": "c", "text": "decision height", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which is the correct sequence for an autoland?', '[{"id": "a", "text": "Localiser capture, glideslope capture, flare and attitude hold", "correct": false}, {"id": "b", "text": "Localiser capture, glideslope capture, attitude hold and flare", "correct": true}, {"id": "c", "text": "Glideslope capture, altitude hold and flare", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A FADEC system does not have the following system?', '[{"id": "a", "text": "Automatic control of engine fire extinguishers", "correct": true}, {"id": "b", "text": "Control of thrust reverser operation", "correct": false}, {"id": "c", "text": "An automatic starting capability", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A full authority Digital Engine Control System (FADEC) consists of', '[{"id": "a", "text": "electronic engine control unit and throttle position transmitter", "correct": false}, {"id": "b", "text": "electronic engine control unit and all its sensors", "correct": true}, {"id": "c", "text": "electronic engine control unit only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When can the FMS be engaged with the autothrottle', '[{"id": "a", "text": "only after take off", "correct": false}, {"id": "b", "text": "With either the Flight Director or the Digital Control System (DFCS) engaged", "correct": true}, {"id": "c", "text": "only with the Flight Director selected", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The stall margin is controlled by', '[{"id": "a", "text": "speed bug cursor", "correct": false}, {"id": "b", "text": "angle of attack and flap position", "correct": true}, {"id": "c", "text": "EPR limits", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft in climb maintains the same IAS. What is it`s true airspeed?', '[{"id": "a", "text": "The same as its IAS", "correct": false}, {"id": "b", "text": "Lower than its IAS", "correct": false}, {"id": "c", "text": "Higher than its IAS", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What type of memory do CMCs have?', '[{"id": "a", "text": "Hard", "correct": false}, {"id": "b", "text": "Non-volatile", "correct": true}, {"id": "c", "text": "Volatile", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the purpose of the tail cone in helicopters?', '[{"id": "a", "text": "To provide vibration damping to the tail rotor", "correct": false}, {"id": "b", "text": "To hold the stabilizers and tail rotor", "correct": true}, {"id": "c", "text": "To provide a balance for CofG", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'in a CMC aircraft, flight deck indications and warnings are managed and provided by', '[{"id": "a", "text": "the engine indicatig and crew alert system (EICAS)", "correct": true}, {"id": "b", "text": "the electronic interface units (EIU)", "correct": false}, {"id": "c", "text": "the central warning computer (CWC)", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The electrolyte in a nicad battery can be checked by checking', '[{"id": "a", "text": "any single cell as all the others will be the same", "correct": false}, {"id": "b", "text": "only the end cell as all the others will be the same", "correct": false}, {"id": "c", "text": "one cell at a time until all cells are completed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An elevator tab moves down', '[{"id": "a", "text": "to counteract for the aircraft flying tail heavy", "correct": false}, {"id": "b", "text": "to make the nose go down", "correct": false}, {"id": "c", "text": "to counteract for the aircraft flying nose heavy", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Weather radar domes are protected from lightning strikes by', '[{"id": "a", "text": "special conducting or non-conducting grease", "correct": false}, {"id": "b", "text": "bonding strips", "correct": true}, {"id": "c", "text": "the use of special conductive paint", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The polythene coating on a HF antenna wire is provided', '[{"id": "a", "text": "to prevent the wire from chafing", "correct": false}, {"id": "b", "text": "to prevent the wire from corroding", "correct": false}, {"id": "c", "text": "to prevent precipitation static build up", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What must be taken into account when measuring the SG or relative density of a lead acid battery?', '[{"id": "a", "text": "The ambient humidity", "correct": false}, {"id": "b", "text": "The ambient pressure", "correct": false}, {"id": "c", "text": "The temperature", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When changing the brushes on a DC generator the brushes must be bedded first, this can be done', '[{"id": "a", "text": "at the manufacturers only", "correct": false}, {"id": "b", "text": "the generator taken off the aircraft and bedding done on the bench", "correct": false}, {"id": "c", "text": "with the generator fitted to the aircraft", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The tail nav light. What angle of divergence should it have?', '[{"id": "a", "text": "140 degrees", "correct": true}, {"id": "b", "text": "120 degrees", "correct": false}, {"id": "c", "text": "180 degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Where does it state what emergency equipment and what levels of emergency equipment should be carried on an aircraft', '[{"id": "a", "text": "JAR OPS (M)", "correct": true}, {"id": "b", "text": "Maintenance Manual", "correct": false}, {"id": "c", "text": "BCAR section A4-8 or A8-4", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a vibrator type voltage regulator', '[{"id": "a", "text": "in series with the voltage coil", "correct": false}, {"id": "b", "text": "parallel with the field", "correct": false}, {"id": "c", "text": "the resistor is in series with the field", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'To improve the image or picture when using the WRX (weather radar receiver)', '[{"id": "a", "text": "use longer bursts", "correct": false}, {"id": "b", "text": "use shorter bursts", "correct": false}, {"id": "c", "text": "scan at a lower rate", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the impedance of VOR or HF aerial cables?', '[{"id": "a", "text": "50 ohms", "correct": true}, {"id": "b", "text": "25 ohms", "correct": false}, {"id": "c", "text": "75 ohms and 25 ohms", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A GCR will trip if what is detected?', '[{"id": "a", "text": "Over current and over frequency", "correct": false}, {"id": "b", "text": "Over frequency and under current", "correct": false}, {"id": "c", "text": "Under frequency and over frequency", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A yaw damper system operates on', '[{"id": "a", "text": "low range frequencies", "correct": false}, {"id": "b", "text": "all yaw frequencies", "correct": false}, {"id": "c", "text": "only mid range frequencies", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Co-ordinated autopilot turns are achieved by', '[{"id": "a", "text": "aileron to elevator crossfeed", "correct": false}, {"id": "b", "text": "aileron to rudder crossfeed", "correct": true}, {"id": "c", "text": "yaw rate gyro signals", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On selection of the Turbulence Mode', '[{"id": "a", "text": "the gain is reduced to prevent stresses to the airframe", "correct": true}, {"id": "b", "text": "the gain remains the same but signals are phase advanced", "correct": false}, {"id": "c", "text": "the gain is doubled to reduce oscillation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'To know the valid data base on the FMS', '[{"id": "a", "text": "call up the relevant page on the CDU", "correct": true}, {"id": "b", "text": "call up the relevant current status", "correct": false}, {"id": "c", "text": "perform a BITE check", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The GA mode is usually initiated by', '[{"id": "a", "text": "pressing a button on thrust levers", "correct": true}, {"id": "b", "text": "making a selection on the mode control panel", "correct": false}, {"id": "c", "text": "pressing a button on the control wheel", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In the FMS vertical navigation (V NAV) climb mode the throttles are used for', '[{"id": "a", "text": "correction minor speed deviations", "correct": false}, {"id": "b", "text": "controlling to a maximum thrust", "correct": true}, {"id": "c", "text": "maintaining a computed EPR", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Synchronisation circuits in autopilots ensure', '[{"id": "a", "text": "that the aircraft will always be returned to straight and level flight when the autopilot is engaged", "correct": false}, {"id": "b", "text": "that the autopilot control circuits are at zero demand conditions engagement", "correct": true}, {"id": "c", "text": "that the trim indicators will read zero prior to engagement", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Automatic trim is used to', '[{"id": "a", "text": "allow full authority to be regained by the aileron", "correct": false}, {"id": "b", "text": "maintain level flight", "correct": false}, {"id": "c", "text": "prevents standing loads on the elevator", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An over station sensor (OSS) is triggered by', '[{"id": "a", "text": "rate of change of radio deviation", "correct": true}, {"id": "b", "text": "rate of change of course", "correct": false}, {"id": "c", "text": "measured radio deviation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'VOR capture can be determined by', '[{"id": "a", "text": "a predetermined level of the VOR deviation signal away from the selected radial", "correct": false}, {"id": "b", "text": "is computed from the vectorial summation of the course error and radio deviation signals", "correct": true}, {"id": "c", "text": "a predetermined level of the course error signal away from the selected radial", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Versine is generated by', '[{"id": "a", "text": "synchros resolvers", "correct": true}, {"id": "b", "text": "control synchro transformers", "correct": false}, {"id": "c", "text": "torque receiver synchros", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The Airworthiness requirements for the autopilot / autoland system are laid down in', '[{"id": "a", "text": "CAIPs", "correct": false}, {"id": "b", "text": "BCARs", "correct": false}, {"id": "c", "text": "JAR AWO", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On the approach the autopilot loses the LOC signal; the aircraft would', '[{"id": "a", "text": "fly parallel to the beam", "correct": false}, {"id": "b", "text": "increase its drift angle", "correct": true}, {"id": "c", "text": "fly a circle", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'To carry out an autopilot check first', '[{"id": "a", "text": "switch on NAV receivers", "correct": false}, {"id": "b", "text": "switch off all power", "correct": false}, {"id": "c", "text": "ensure all control surfaces are unobstructed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which modes are incompatible', '[{"id": "a", "text": "HDG + V/S HOLD", "correct": false}, {"id": "b", "text": "G/S + ALTITUDE HOLD", "correct": true}, {"id": "c", "text": "VOR + ALTITUDE HOLD", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'With autothrottle selected in the SPEED MODE compatible autopilot modes are', '[{"id": "a", "text": "V/S and ALT ARM", "correct": true}, {"id": "b", "text": "IAS HOLD and ALT ARM", "correct": false}, {"id": "c", "text": "VOR ARM and HDG HOLD", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stand off errors on localiser approach are washed out by', '[{"id": "a", "text": "integrating deviation signal", "correct": true}, {"id": "b", "text": "integrating course error", "correct": false}, {"id": "c", "text": "differentiating deviation signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'in a triplex system, the detection of a failure of one simplex system will disconnect', '[{"id": "a", "text": "the failed system and continue with a manual approach", "correct": false}, {"id": "b", "text": "all channels", "correct": false}, {"id": "c", "text": "the failed system and carry on with an autoland", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The purpose of a yaw damper is to', '[{"id": "a", "text": "produce a co-ordinated turn", "correct": false}, {"id": "b", "text": "block the Dutch roll frequency", "correct": true}, {"id": "c", "text": "assist the aerodynamic response", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A category 3B aircraft using fail operational automatic landing equipment which fail operational control and roll out guidance will have', '[{"id": "a", "text": "a decision height depending upon the RVR", "correct": false}, {"id": "b", "text": "no decision height", "correct": true}, {"id": "c", "text": "a decision height of about 50 feet", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Runway visual range in (RVR) is obtained by', '[{"id": "a", "text": "one set of instruments the threshold of the runway", "correct": false}, {"id": "b", "text": "three sets of instruments at the side of the runway", "correct": true}, {"id": "c", "text": "information obtained the local Meteorological Office", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The International Civil Aviation Organisation weather category 3A is', '[{"id": "a", "text": "operation down to and along the surface of the runway with RVR of 200 meters", "correct": true}, {"id": "b", "text": "operation down to sixty meters and RVR of 800 meters", "correct": false}, {"id": "c", "text": "operation down to and along the surface of the runway without external reference", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The wheel height at which the approach path has been visually assessed as satisfactory to continue the approach to a landing is known as the', '[{"id": "a", "text": "alert height", "correct": false}, {"id": "b", "text": "intercept height", "correct": false}, {"id": "c", "text": "decision height", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Overshoot or go-around mode can be initiated', '[{"id": "a", "text": "at any time", "correct": true}, {"id": "b", "text": "after glideslope capture", "correct": false}, {"id": "c", "text": "only when autopilot is engaged", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An automatic throttle, engaged in the EPR mode, will control', '[{"id": "a", "text": "the engine throttles to maintain a constant engine power setting", "correct": true}, {"id": "b", "text": "the engine throttles to maintain a constant acceleration rate", "correct": false}, {"id": "c", "text": "the aircraft altitude to maintain constant engine input pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'the aircraft decrabbing signal, used during autoland, originates from', '[{"id": "a", "text": "heading errors", "correct": true}, {"id": "b", "text": "localiser deviation errors", "correct": false}, {"id": "c", "text": "roll errors", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'during an automatic landing, the aircraft descent rate is sensed by', '[{"id": "a", "text": "vertical accelerometers", "correct": false}, {"id": "b", "text": "radio altimeters", "correct": true}, {"id": "c", "text": "pitch rate gyros", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A full operational autopilot system will ensure that', '[{"id": "a", "text": "the aircraft will continue its automatic landing in the event of a single failure", "correct": true}, {"id": "b", "text": "the automatic pilot will automatically cause the aircraft to overshoot if any failure is detected", "correct": false}, {"id": "c", "text": "the automatic pilot will automatically disengage whenever any failure is detected", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What happens when battery master is switched off in flight?', '[{"id": "a", "text": "Electrical systems shut down", "correct": false}, {"id": "b", "text": "No effect", "correct": false}, {"id": "c", "text": "Battery disconnected from charge circuit", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If on a lead-acid battery, several cell checks of SG read consistently low. Battery needs', '[{"id": "a", "text": "recharging", "correct": true}, {"id": "b", "text": "replacing", "correct": false}, {"id": "c", "text": "topping up with distilled water", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How many satellites required for GNS?', '[{"id": "a", "text": "6 90o apart", "correct": false}, {"id": "b", "text": "8", "correct": false}, {"id": "c", "text": "4", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When OAT increases what happens to an helicopter operating ceiling?', '[{"id": "a", "text": "No effect", "correct": false}, {"id": "b", "text": "Decrease", "correct": true}, {"id": "c", "text": "Increase", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Relative velocity of rotor', '[{"id": "a", "text": "is equal for all blades", "correct": false}, {"id": "b", "text": "increases at retreating blade", "correct": false}, {"id": "c", "text": "increases at fwd travelling blade", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What design factors govern RPM of a helicopter rotor?', '[{"id": "a", "text": "Fineness ratio", "correct": false}, {"id": "b", "text": "Engine and gearbox", "correct": true}, {"id": "c", "text": "Weight of blade", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What damps vibrations on a helicopter?', '[{"id": "a", "text": "Scissor levers", "correct": false}, {"id": "b", "text": "Swashplate", "correct": false}, {"id": "c", "text": "Pfifer damper", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What effect does the ground have on a helicopter?', '[{"id": "a", "text": "Increases thrust", "correct": false}, {"id": "b", "text": "No effect", "correct": false}, {"id": "c", "text": "Increases lift", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which side of the pilot is the collective?', '[{"id": "a", "text": "In-between legs", "correct": false}, {"id": "b", "text": "Right", "correct": false}, {"id": "c", "text": "Left", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Maximum power on a wave guide is governed by the', '[{"id": "a", "text": "number of joints and bends", "correct": false}, {"id": "b", "text": "narrowest width", "correct": true}, {"id": "c", "text": "widest width", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Adding 6 foot of cable to TX RX aerials on rad alt would give you', '[{"id": "a", "text": "12 foot error", "correct": false}, {"id": "b", "text": "6ft error", "correct": true}, {"id": "c", "text": "3 ft error", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If radar pulse is reduced there is', '[{"id": "a", "text": "no effect", "correct": false}, {"id": "b", "text": "reduced relative range", "correct": true}, {"id": "c", "text": "increased relative range", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What frequency increases radar relative range', '[{"id": "a", "text": "Radar relative range cannot be increased by frequency change", "correct": true}, {"id": "b", "text": "low", "correct": false}, {"id": "c", "text": "high", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is power at pulse?', '[{"id": "a", "text": "Average power", "correct": false}, {"id": "b", "text": "Pulsed power", "correct": false}, {"id": "c", "text": "Peak power", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Aircraft is North of VOR beacon on a course of 090 RMI pointer points to', '[{"id": "a", "text": "180", "correct": true}, {"id": "b", "text": "090", "correct": false}, {"id": "c", "text": "0", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Buffer amp on transmitter is between', '[{"id": "a", "text": "local oscillator and demodulator", "correct": false}, {"id": "b", "text": "local oscillator and modulator", "correct": true}, {"id": "c", "text": "modulator and power amp", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Galley and cabin lighting operate on', '[{"id": "a", "text": "GND services", "correct": false}, {"id": "b", "text": "AC bus", "correct": true}, {"id": "c", "text": "DC bus", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How does a balance tab move?', '[{"id": "a", "text": "In the opposite direction proportional to the control surface it is attached to", "correct": true}, {"id": "b", "text": "In the same direction a small amount", "correct": false}, {"id": "c", "text": "In the same direction proportional to the control surface it is attached to", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What does a trim tab do?', '[{"id": "a", "text": "Provides finer control movements by the pilot", "correct": false}, {"id": "b", "text": "Allows the C of G to be outside the normal limit", "correct": false}, {"id": "c", "text": "Eases control loading for pilot", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If you add an aerial, to strengthen the airframe you add', '[{"id": "a", "text": "an intercostals", "correct": false}, {"id": "b", "text": "external doubler", "correct": false}, {"id": "c", "text": "an internal doubler", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What controls pitch and roll on a delta wing aircraft?', '[{"id": "a", "text": "Elevons", "correct": true}, {"id": "b", "text": "Ailerons", "correct": false}, {"id": "c", "text": "Elevators", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On a helicopter what is dragging?', '[{"id": "a", "text": "Contact of the blade tips on the ground", "correct": false}, {"id": "b", "text": "Movement of each blade horizontally about their vertical hinge", "correct": true}, {"id": "c", "text": "Movement of each blade vertically about their lateral hinges", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What do ruddervators do?', '[{"id": "a", "text": "Control yaw and roll", "correct": false}, {"id": "b", "text": "Control pitch and roll", "correct": false}, {"id": "c", "text": "Control pitch and yaw", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What preventative maintenance can be carried out in case of HIRF?', '[{"id": "a", "text": "Shielding of all sensitive equipment", "correct": false}, {"id": "b", "text": "Bonding and insulation tests", "correct": true}, {"id": "c", "text": "Check of aircraft structure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Pushing the left rudder pedal', '[{"id": "a", "text": "yaws the aircraft left but has no effect on the wing", "correct": false}, {"id": "b", "text": "yaws the aircraft left and possibly the left wing will rise", "correct": false}, {"id": "c", "text": "yaws the aircraft left and possibly the right wing will rise", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Lowering of the flaps', '[{"id": "a", "text": "increases lift", "correct": false}, {"id": "b", "text": "increases drag", "correct": false}, {"id": "c", "text": "increases drag and lift", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Flaps at landing position', '[{"id": "a", "text": "decrease landing speed", "correct": true}, {"id": "b", "text": "decrease take off speed", "correct": false}, {"id": "c", "text": "decrease take off and landing speed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a dual FMS, a failure of one computer will result in', '[{"id": "a", "text": "a blank display on one CDU", "correct": false}, {"id": "b", "text": "a down grade of the landing category", "correct": false}, {"id": "c", "text": "no effect on the CDU di", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When a compass is in the slave mode', '[{"id": "a", "text": "the azimuth gyro will wander uncompensated", "correct": false}, {"id": "b", "text": "azimuth gyro will be corrected by long term monitoring of the flux valve", "correct": true}, {"id": "c", "text": "the azimuth gyro is slaved to the annunciator or synchroniser circuit", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Versine signal is governed by', '[{"id": "a", "text": "roll", "correct": true}, {"id": "b", "text": "pitch", "correct": false}, {"id": "c", "text": "yaw", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Anti cross-talk network for unwanted signals uses', '[{"id": "a", "text": "attenuation first then amplification", "correct": true}, {"id": "b", "text": "amplification first the", "correct": false}, {"id": "c", "text": "no attenuation but amplification", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In audio clipping', '[{"id": "a", "text": "vowels are strengthened relative to the remaining signal", "correct": false}, {"id": "b", "text": "vowels are attenuated relative to the remaining signal", "correct": true}, {"id": "c", "text": "there is no change in relative strength of vowels", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'For a Vertical Gyro which is moved in pitch, which gimble would be moved to correct the pitch movement?', '[{"id": "a", "text": "Lateral", "correct": true}, {"id": "b", "text": "Longitudinal", "correct": false}, {"id": "c", "text": "Normal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If one FMS fails in a dual system', '[{"id": "a", "text": "system operation will not be affected", "correct": false}, {"id": "b", "text": "FMS CDU on fail side goes blank", "correct": false}, {"id": "c", "text": "FMS display transfers automatically from serviceable computer", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'After a change in pitch of a rotor blade the blade will be at maximum flap at', '[{"id": "a", "text": "90 o", "correct": true}, {"id": "b", "text": "180 o", "correct": false}, {"id": "c", "text": "0 o", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ATCRBS reply pulses are', '[{"id": "a", "text": "0.8 s wide", "correct": false}, {"id": "b", "text": "0.45 s wide", "correct": true}, {"id": "c", "text": "1.45 s wide", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Range resolution in a radars', '[{"id": "a", "text": "shorter Pulse", "correct": true}, {"id": "b", "text": "longer Pulse", "correct": false}, {"id": "c", "text": "narrower Beam", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Rear navigation lights have', '[{"id": "a", "text": "steady white light with a viewing angle of 60 degrees", "correct": false}, {"id": "b", "text": "flashing white light with a viweing angle of 60 degrees", "correct": false}, {"id": "c", "text": "steady white light with a viewing angle of 140 degrees", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Runway turn off lights have a viewing angle of', '[{"id": "a", "text": "50 degrees", "correct": true}, {"id": "b", "text": "110 degrees", "correct": false}, {"id": "c", "text": "160 degrees", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Using the following: FS 345, RWS 45, where is this located?', '[{"id": "a", "text": "345\" back from the nose, 45\" from the longitudinal centre line of the right wing", "correct": false}, {"id": "b", "text": "345\" back from the datum line, 45\" from the longitudinal centre line of the right wing", "correct": true}, {"id": "c", "text": "345\" back from the nose and 45\" along the right wing", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Slewing of the INS gimballed platform simulates in-flight attitude changes up to', '[{"id": "a", "text": "360 deg in roll and 85 deg in pitch", "correct": false}, {"id": "b", "text": "71 deg in pitch and 180 deg in azimuth", "correct": true}, {"id": "c", "text": "110 deg in pitch and 360 deg in azimuth", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Cyclic shift of the stator connections in a torque synchro results in', '[{"id": "a", "text": "output datum advanced 180 deg", "correct": false}, {"id": "b", "text": "data to coincide", "correct": false}, {"id": "c", "text": "output datum advanced 240 deg", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Gimbal lock in a displacement gyro occurs when', '[{"id": "a", "text": "spin axis becomes coincident with any of the axis of freedom", "correct": true}, {"id": "b", "text": "gimbal rings are mutually not at right angles to each other", "correct": false}, {"id": "c", "text": "bearing friction causes gimbal system to unbalance", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a turn co-ordinator the output axis of the rate gyro is', '[{"id": "a", "text": "parallel to the longitudinal axis of the aircraft", "correct": false}, {"id": "b", "text": "set at 30 deg to the longitudinal axis", "correct": true}, {"id": "c", "text": "parallel to the lateral axis to make the gyro sensitive to rolling and banking as well as turning", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'All fly to information in an EFIS System is displayed in', '[{"id": "a", "text": "White", "correct": false}, {"id": "b", "text": "Magenta", "correct": true}, {"id": "c", "text": "Green", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In an EICAS display all scales, normal operating range of pointers and digital readouts a', '[{"id": "a", "text": "White", "correct": false}, {"id": "b", "text": "green", "correct": true}, {"id": "c", "text": "Magenta", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The scratch pad in an FMS CDU occupies', '[{"id": "a", "text": "24 character spaces of the bottom line", "correct": true}, {"id": "b", "text": "the last 12 character spaces of the bottom line", "correct": false}, {"id": "c", "text": "first 12 character spaces of the bottom line", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The term oblate spheroid refers to', '[{"id": "a", "text": "tilting of the earth about the axis", "correct": false}, {"id": "b", "text": "flattening at the Polar Regions", "correct": true}, {"id": "c", "text": "the network of meridians imagined to cover the earth", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The horizontal angle contained between the true and the magnetic meridian at any place is', '[{"id": "a", "text": "inclination", "correct": false}, {"id": "b", "text": "declination", "correct": true}, {"id": "c", "text": "angle of dip", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Thermocouple combination mostly used for exhaust gas temperature indications are', '[{"id": "a", "text": "Copper-Constantan", "correct": false}, {"id": "b", "text": "Iron-Constantan", "correct": false}, {"id": "c", "text": "Chromel-Alumel", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Wing loading of an aircraft', '[{"id": "a", "text": "varies with dynamic loading due to air currents", "correct": false}, {"id": "b", "text": "is independent of altitude", "correct": true}, {"id": "c", "text": "decreases with density", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Glide slope frequency is', '[{"id": "a", "text": "108.10-119.95", "correct": false}, {"id": "b", "text": "328.6-335.4", "correct": true}, {"id": "c", "text": "108.00-118", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ADF operation range is at', '[{"id": "a", "text": "MF band", "correct": true}, {"id": "b", "text": "HF band", "correct": false}, {"id": "c", "text": "VHF band", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Outer marker frequency is', '[{"id": "a", "text": "3000 hz", "correct": false}, {"id": "b", "text": "1300 hz", "correct": false}, {"id": "c", "text": "400 hz", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Tripping the GCR will', '[{"id": "a", "text": "trip the GCB", "correct": false}, {"id": "b", "text": "de-excite the generator", "correct": false}, {"id": "c", "text": "both (a) and (b)", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a synchronous motor the rotor is', '[{"id": "a", "text": "excited by DC", "correct": true}, {"id": "b", "text": "excited by AC", "correct": false}, {"id": "c", "text": "self excited", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'the difference between synchronous speed and rotor speed is called', '[{"id": "a", "text": "differential speed", "correct": false}, {"id": "b", "text": "loss", "correct": false}, {"id": "c", "text": "slip", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A squirrel cage rotor will be found in', '[{"id": "a", "text": "an induction motor", "correct": true}, {"id": "b", "text": "a synchronous motor", "correct": false}, {"id": "c", "text": "a hysteresis motor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Airspeeds above the speed of sound, but not exceeding 4 times the speed of sound are', '[{"id": "a", "text": "hypersonic", "correct": false}, {"id": "b", "text": "supersonic", "correct": true}, {"id": "c", "text": "hyposonic", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is a fairlead?', '[{"id": "a", "text": "A guide for control cables running through bulkheads etc", "correct": true}, {"id": "b", "text": "A guard to prevent control cables coming off pulleys", "correct": false}, {"id": "c", "text": "An extension to a control cable", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'FMC provides data envelope for', '[{"id": "a", "text": "ATC", "correct": false}, {"id": "b", "text": "TCAS", "correct": false}, {"id": "c", "text": "GPWS", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In an EICAS system, operation of the cancel switch', '[{"id": "a", "text": "removes all messages from the display", "correct": false}, {"id": "b", "text": "removes caution and advisory messages", "correct": true}, {"id": "c", "text": "removes advisory messages", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The true airspeed output from a CADC will be determined by information fed from', '[{"id": "a", "text": "The Pitot and Static sensors", "correct": false}, {"id": "b", "text": "The Mach unit", "correct": false}, {"id": "c", "text": "The Mach unit and Temperature Sensor", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The alignment position of an IR Mode Selector unit enables', '[{"id": "a", "text": "the accelerometers to correct the axes", "correct": false}, {"id": "b", "text": "sets the start co- ordinates", "correct": false}, {"id": "c", "text": "Gyro run up, levelling, azimuth determination", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Pin Programming is allowed', '[{"id": "a", "text": "under CAA Rules", "correct": false}, {"id": "b", "text": "to provide reference to FMS computer as to which side of datum it is fitted to", "correct": true}, {"id": "c", "text": "to enter aircraft performance data base", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The Janus beam is for', '[{"id": "a", "text": "working out acceleration", "correct": false}, {"id": "b", "text": "levelling the aerial", "correct": false}, {"id": "c", "text": "to compensate for attitude changes", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A combined ASI indicates Mach', '[{"id": "a", "text": "above 0.15", "correct": false}, {"id": "b", "text": "above 10000 feet", "correct": true}, {"id": "c", "text": "all the time airspeed present", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Sonar Locator Beacons are a', '[{"id": "a", "text": "ICAO Requirement", "correct": true}, {"id": "b", "text": "ANO Requirement", "correct": false}, {"id": "c", "text": "Company Requi", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'INS power is provided by', '[{"id": "a", "text": "DC normal and DC emerge", "correct": false}, {"id": "b", "text": "AC normal and DC emergency", "correct": true}, {"id": "c", "text": "AC normal and AC emergen y", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Aircraft is 9000 ft. When is it out of VHF range', '[{"id": "a", "text": "100 nm", "correct": false}, {"id": "b", "text": "120 nm", "correct": true}, {"id": "c", "text": "140 nm", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A semi monocoque structure is one which has', '[{"id": "a", "text": "an external load bearing skin with no internal load bearing structure", "correct": false}, {"id": "b", "text": "an external load bearing skin with internal load bearing structure", "correct": true}, {"id": "c", "text": "a tubular internal structure fabric covered", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which of the following is correct?', '[{"id": "a", "text": "feedback = error - demand", "correct": false}, {"id": "b", "text": "error = demand - feedback", "correct": true}, {"id": "c", "text": "demand = feedback - error", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A member designed to take mainly compressive load is called a', '[{"id": "a", "text": "tie", "correct": false}, {"id": "b", "text": "beam", "correct": false}, {"id": "c", "text": "strut", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Longitudinal members in a semi-monocoque fuselage supporting the skin between longerons are called', '[{"id": "a", "text": "ribs", "correct": false}, {"id": "b", "text": "stringers", "correct": true}, {"id": "c", "text": "frames", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A modern large transport aircraft fuselage would be normally be constructed from', '[{"id": "a", "text": "warren truss structure", "correct": false}, {"id": "b", "text": "semi monocoque structure", "correct": true}, {"id": "c", "text": "geodetic structure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the common portion of the winding of a autotransformer used to supply a 26 vac light bulb from a 115 vac busbar goes open circuit the light bulb will', '[{"id": "a", "text": "flicker", "correct": false}, {"id": "b", "text": "go dim", "correct": false}, {"id": "c", "text": "blow", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'MCDUs', '[{"id": "a", "text": "are used to transmit dat to ground", "correct": false}, {"id": "b", "text": "enable dialog with cent", "correct": true}, {"id": "c", "text": "store fault data", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The uploading function on a on -board maintenance system enables', '[{"id": "a", "text": "data to be taken from on-board maintenance system", "correct": false}, {"id": "b", "text": "the on-board data base to be updated", "correct": true}, {"id": "c", "text": "the on-board maintenance system to be interrogated by the engineer", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If the output of the generator starts to fall, a pulse width modulated field supply will', '[{"id": "a", "text": "increase the mark-to -space ratio", "correct": true}, {"id": "b", "text": "decrease the mark-to- space ratio", "correct": false}, {"id": "c", "text": "double the mark-to-space ratio", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a starter generator which coil is used for starting?', '[{"id": "a", "text": "Shunt, series and compensating windings", "correct": true}, {"id": "b", "text": "series compensating windings", "correct": false}, {"id": "c", "text": "Shunt compensating windings", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A gate valve is installed in a vacuum system is to prevent', '[{"id": "a", "text": "back pressure due to engine surge", "correct": false}, {"id": "b", "text": "oil entering gyro when shut down", "correct": true}, {"id": "c", "text": "reverse flow due to engine backfire", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Normal vertical minimum separation allowed is', '[{"id": "a", "text": "800 ft", "correct": false}, {"id": "b", "text": "1000 ft", "correct": false}, {"id": "c", "text": "2000 ft", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The venturi tubes in a vacuum instrument are measured in', '[{"id": "a", "text": "Millibars", "correct": false}, {"id": "b", "text": "Inches of Mercury", "correct": true}, {"id": "c", "text": "PSI", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Before processing an AM USB signal what needs to be done?', '[{"id": "a", "text": "Carrier added", "correct": true}, {"id": "b", "text": "Carrier removed", "correct": false}, {"id": "c", "text": "Carrier integrated", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On power up, IRS', '[{"id": "a", "text": "obtains latitude from previous position", "correct": false}, {"id": "b", "text": "compares longitude from previous position", "correct": false}, {"id": "c", "text": "obtains both from previous position", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The instrument supplied with pitot and is affected by altitude is a', '[{"id": "a", "text": "ASI", "correct": true}, {"id": "b", "text": "VSI", "correct": false}, {"id": "c", "text": "Mach Meter", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Speed mode stall margins are governed by', '[{"id": "a", "text": "AOA and flap position", "correct": true}, {"id": "b", "text": "Pitch angle and speed", "correct": false}, {"id": "c", "text": "AOA and speed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When performing an ADF bearing check, commercial stations', '[{"id": "a", "text": "can be used", "correct": false}, {"id": "b", "text": "can be used in addition to ADF nav stations", "correct": true}, {"id": "c", "text": "can not be used as they are the wrong frequency", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A fuel system that corrects fuel SG is calibrated in', '[{"id": "a", "text": "Pounds or KGs", "correct": true}, {"id": "b", "text": "Litres", "correct": false}, {"id": "c", "text": "Gallons", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In ground mode the FMS uses which of the following for velocity calculations?', '[{"id": "a", "text": "IRS", "correct": true}, {"id": "b", "text": "RHO-RHO", "correct": false}, {"id": "c", "text": "RHO-THETA", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Confirmation of the correct operation of an ATC transponder ident function, is verified by', '[{"id": "a", "text": "use of a ramp test set", "correct": true}, {"id": "b", "text": "observation of the ATC transponder control head ident light", "correct": false}, {"id": "c", "text": "telephone contact with the receiving ATC cell", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'IRS serviceability for in-service drift is ascertained by', '[{"id": "a", "text": "3+3t", "correct": false}, {"id": "b", "text": "CDU fault code interrogation", "correct": false}, {"id": "c", "text": "apparent drift divided by flight time", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a IRS system the accelerometer is double interrogated for', '[{"id": "a", "text": "distance", "correct": true}, {"id": "b", "text": "acceleration", "correct": false}, {"id": "c", "text": "velocity", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In flight mode, the FMS preference of data source is', '[{"id": "a", "text": "IRS, RHO-RHO, RHO-THETA", "correct": false}, {"id": "b", "text": "RHO-RHO, IRS, RHO-THETA", "correct": true}, {"id": "c", "text": "RHO-THETA, RHO-RHO, IRS", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In aileron control', '[{"id": "a", "text": "the up going aileron moves further than down going aileron", "correct": true}, {"id": "b", "text": "the down going aileron moves further than up going aileron", "correct": false}, {"id": "c", "text": "it is assisted by the rudder", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Janus in doppler radar', '[{"id": "a", "text": "Adjusts signal for overwater flight", "correct": false}, {"id": "b", "text": "allows adjustment for antenna pitch", "correct": true}, {"id": "c", "text": "adjusts for lateral and vertical steering", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ATC altitude readout is', '[{"id": "a", "text": "series Tx with binary encoding", "correct": false}, {"id": "b", "text": "series Tx with octal encoding", "correct": false}, {"id": "c", "text": "parallel Tx with binary encoding", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Stab trim goes into high speed mode when', '[{"id": "a", "text": "Flaps are extended", "correct": true}, {"id": "b", "text": "Flaps are retracted", "correct": false}, {"id": "c", "text": "cruise altitude is reached", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A standby artificial horizon is a', '[{"id": "a", "text": "space gyro", "correct": false}, {"id": "b", "text": "earth gyro", "correct": true}, {"id": "c", "text": "free gyro", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Pitot static lines in helicopters', '[{"id": "a", "text": "are made of stainless steel, and must withstand twice normal working pressure", "correct": false}, {"id": "b", "text": "must provide an accurate indication of the flight regime below 20 knots", "correct": false}, {"id": "c", "text": "must provide accurate information over the helicopter certified flight envolope", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the main operating principle of MLS?', '[{"id": "a", "text": "phase shift between Tx and Rx", "correct": false}, {"id": "b", "text": "time difference between TO and FRO pulse", "correct": true}, {"id": "c", "text": "signal strength (mV) difference between left and right beam", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How does a Rx know whether an ILS or a VOR frequency has been selected?', '[{"id": "a", "text": "Manually selected by operator", "correct": false}, {"id": "b", "text": "Logic control circuit in control unit", "correct": true}, {"id": "c", "text": "A different receiver is used", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the purpose of the current transformer on a Neutral phase of an AC generator?', '[{"id": "a", "text": "Negative phase sequencing", "correct": false}, {"id": "b", "text": "Open phase", "correct": false}, {"id": "c", "text": "Differential protection", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An aircraft is on course on an ILS Localiser. What is the depth of modulation?', '[{"id": "a", "text": "zero", "correct": false}, {"id": "b", "text": "20%", "correct": true}, {"id": "c", "text": "50%", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the term used for the amount of water in the atmosphere?', '[{"id": "a", "text": "Relative humidity", "correct": false}, {"id": "b", "text": "Absolute humidity", "correct": true}, {"id": "c", "text": "Dew point", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How is the flight deck informed of an ACARS transmission?', '[{"id": "a", "text": "SELCAL", "correct": false}, {"id": "b", "text": "ONSIDE VHF T/R", "correct": false}, {"id": "c", "text": "A double chime", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a FBW system, a complete failure of the electronic flight control system in pitch', '[{"id": "a", "text": "is not possible because of the built-in redundancy for all elements", "correct": false}, {"id": "b", "text": "would require the aircraft to be manually controlled in pitch using pitch trim wheel", "correct": true}, {"id": "c", "text": "would cause the captain`s sidestick controller to take over pitch functions", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Capture of a localiser beam is normally dependent on a change of bank angle command based on', '[{"id": "a", "text": "airspeed, deviation and altitude", "correct": false}, {"id": "b", "text": "attitude, distance from transmitter and runway heading", "correct": false}, {"id": "c", "text": "ground speed, intercept angle and distance form beam", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The flight data recorder underwater locator beacon operates at a frequency of thirty seven kilo- hertz', '[{"id": "a", "text": "with an operational time of at least thirty days", "correct": true}, {"id": "b", "text": "and has a maximum detection range of two thousand to four thousand feet", "correct": false}, {"id": "c", "text": "and is able to withstand immersion to twenty thousand metres", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Panels that are attached to the aircraft by answered questionfasteners are:', '[{"id": "a", "text": "tertiary structure", "correct": false}, {"id": "b", "text": "secondary structure", "correct": true}, {"id": "c", "text": "primary structure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Movement of the collective control will', '[{"id": "a", "text": "increase the pitch of the tail rotor", "correct": false}, {"id": "b", "text": "tilt the disc and increase engine power", "correct": false}, {"id": "c", "text": "increase the pitch of the main rotor blades", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Gust Load Alleviation Function in a FBW system', '[{"id": "a", "text": "may be controlled by the elevators", "correct": false}, {"id": "b", "text": "uses the high speed computer responses to compensate for sudden gusts", "correct": true}, {"id": "c", "text": "is achieved by the weight saving from elimination of cables, feel units and other conventional items", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Active load control on a large transport aircraft`s aileron system is fitted to', '[{"id": "a", "text": "increase roll control authority of the autopilot", "correct": false}, {"id": "b", "text": "improve trim control due to lateral centre of gravity changes", "correct": false}, {"id": "c", "text": "improve fatigue life, due to aero elasticity and high lift loads", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If earthing jumper leads terminate to a connector strain clamp, the expected resistance value when carrying out a check should be', '[{"id": "a", "text": "0.5 milliohms", "correct": true}, {"id": "b", "text": "1.5 milliohms", "correct": false}, {"id": "c", "text": "2.5 milliohms", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An extruded or rolled aluminium sheet channel section that runs normally the length of the fuselage is known as', '[{"id": "a", "text": "intercostal", "correct": false}, {"id": "b", "text": "stringer", "correct": true}, {"id": "c", "text": "cleat", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A panel at STN + 88 /WL -12 is located 88 units', '[{"id": "a", "text": "rearward of the aircraft datum and 12 units above the water line datum", "correct": false}, {"id": "b", "text": "forward of the aircraft vertical centre and 12 units below the water line datum", "correct": false}, {"id": "c", "text": "rearward of the datum and 12 units below the waterline", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Cantilever construction is structure supported at', '[{"id": "a", "text": "each end and in the centre", "correct": false}, {"id": "b", "text": "one end only", "correct": true}, {"id": "c", "text": "each end", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A fuselage construction where the skin carries all of the loads is known as:', '[{"id": "a", "text": "semi-monocoque", "correct": false}, {"id": "b", "text": "semi-stressed", "correct": false}, {"id": "c", "text": "monocoque", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When the rotor of an ac tacho-generator is stationary, the rotor has', '[{"id": "a", "text": "no circulating currents", "correct": false}, {"id": "b", "text": "circulating currents", "correct": true}, {"id": "c", "text": "no magnetic field", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An AC tacho-generator stator has', '[{"id": "a", "text": "two windings 180 apart", "correct": false}, {"id": "b", "text": "three windings 120 apart", "correct": false}, {"id": "c", "text": "two windings 90 apart", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A leak in the static line in a pressurised part of an aircraft can cause the mach indication to', '[{"id": "a", "text": "rise", "correct": false}, {"id": "b", "text": "decrease", "correct": true}, {"id": "c", "text": "no change", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A control surface which forms a slot when deployed is called', '[{"id": "a", "text": "slat", "correct": true}, {"id": "b", "text": "slot", "correct": false}, {"id": "c", "text": "flap", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'During helicopter forward flight the retreating blade will tend to', '[{"id": "a", "text": "flap up", "correct": false}, {"id": "b", "text": "no change", "correct": false}, {"id": "c", "text": "flap down", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Asymmetric flaps will cause', '[{"id": "a", "text": "the aircraft to ascend", "correct": false}, {"id": "b", "text": "one wing to rise", "correct": true}, {"id": "c", "text": "the aircraft to descend", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'How many satellites comprise the space segment for GPS?', '[{"id": "a", "text": "4 satellites in six orbits", "correct": true}, {"id": "b", "text": "6 satellites in four orbits", "correct": false}, {"id": "c", "text": "8 satellites in three orbits", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ACARS message is transmitted in which word format?', '[{"id": "a", "text": "Binary", "correct": true}, {"id": "b", "text": "Hex", "correct": false}, {"id": "c", "text": "Decimal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What type of system is an ADF?', '[{"id": "a", "text": "rho", "correct": false}, {"id": "b", "text": "theta", "correct": true}, {"id": "c", "text": "rho-theta", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Small pins on an AC GPU receptacle', '[{"id": "a", "text": "prevent arcing when inserting or removing the connector", "correct": false}, {"id": "b", "text": "use AC as part of an interlock circuit", "correct": true}, {"id": "c", "text": "are used to prevent incorrect orientation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mach meter is', '[{"id": "a", "text": "not square law compensated", "correct": false}, {"id": "b", "text": "is automatically compensated", "correct": true}, {"id": "c", "text": "is compensated with square law screws and an arm", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mach meter reads the correct value', '[{"id": "a", "text": "above 10,000 feet only", "correct": false}, {"id": "b", "text": "at sea level only", "correct": false}, {"id": "c", "text": "at any altitude", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Battery charging on an aircraft', '[{"id": "a", "text": "may produce excessive charging initially, especially if the battery charge is low", "correct": true}, {"id": "b", "text": "will be reasonably stable due to constant voltage charging", "correct": false}, {"id": "c", "text": "will be reasonably stable due to constant current charging", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A vibrating contact voltage regulator', '[{"id": "a", "text": "has a resistor in parallel with the two contacts", "correct": true}, {"id": "b", "text": "has a resistor in series with the two contacts", "correct": false}, {"id": "c", "text": "has a resistor in series with the voltage coil", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A fuel system that measures SG will be displayed in', '[{"id": "a", "text": "Lbs or kgs", "correct": true}, {"id": "b", "text": "Ltrs or gals", "correct": false}, {"id": "c", "text": "Ltrs or kgs", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'When a helicopter rotor disc is tilted forward, what happens to the pitch of the retreating blade?', '[{"id": "a", "text": "Increases", "correct": true}, {"id": "b", "text": "Decreases", "correct": false}, {"id": "c", "text": "Remains constant", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Data communication between the aircraft and the operational control centre is possible through', '[{"id": "a", "text": "selcal system", "correct": false}, {"id": "b", "text": "ACARS system", "correct": true}, {"id": "c", "text": "satcom system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which is not displayed on an attitude director indicator (ADI)', '[{"id": "a", "text": "glide slope deviation", "correct": false}, {"id": "b", "text": "localizer deviation", "correct": false}, {"id": "c", "text": "VOR lateral deviation", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'If a ground station interrogating an aircraft transmits P1, P2 and P6 through the rotating beam antenna and P5 is radiated by omni -directional antenna, which mode is it addressing', '[{"id": "a", "text": "Mode A and C only", "correct": false}, {"id": "b", "text": "Mode S only", "correct": true}, {"id": "c", "text": "Mode A&C and S", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Which of the following navigation system is not a hyperbolic navigation system', '[{"id": "a", "text": "Loran C", "correct": false}, {"id": "b", "text": "VLF omega", "correct": false}, {"id": "c", "text": "Doppler", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The length of a resonant antenna dipole is', '[{"id": "a", "text": "lambda", "correct": false}, {"id": "b", "text": "lambda/2", "correct": true}, {"id": "c", "text": "lambda/4", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A typical emergency locator transmitter (ELT)', '[{"id": "a", "text": "receives 2 frequencies", "correct": false}, {"id": "b", "text": "transmit 3 frequencies", "correct": false}, {"id": "c", "text": "transmits 2 frequencies", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The pulse repetition frequency (PRF)', '[{"id": "a", "text": "high for long ranges", "correct": false}, {"id": "b", "text": "low for long ranges", "correct": true}, {"id": "c", "text": "low for short ranges", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Radio altimeter (radar) normally indicates the altitude of', '[{"id": "a", "text": "plus-minus 2500feet", "correct": false}, {"id": "b", "text": "to 2500feet pressure altitude", "correct": false}, {"id": "c", "text": "0 to 2500 feet above the ground level", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GPS consists of 24 orbiting satellites located', '[{"id": "a", "text": "10,900 nautical miles (approximately 20,200 km)", "correct": true}, {"id": "b", "text": "in a 5000 miles high orbit", "correct": false}, {"id": "c", "text": "in a 8800 miles high orbit", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The path of a point which moves such that the difference in distance from two fixed points is called', '[{"id": "a", "text": "parabola", "correct": false}, {"id": "b", "text": "circle", "correct": false}, {"id": "c", "text": "hyperbola", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A selcal signal transmits', '[{"id": "a", "text": "a pair of tones continuously", "correct": false}, {"id": "b", "text": "four tones continuously", "correct": false}, {"id": "c", "text": "two pair of tones-one pair after the other", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The frequency of 111.1 MHz is used by', '[{"id": "a", "text": "ILS localiser", "correct": true}, {"id": "b", "text": "VOR", "correct": false}, {"id": "c", "text": "ILS glideslope", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In VOR the manual phase shift resolver is a', '[{"id": "a", "text": "30 Hz signal", "correct": true}, {"id": "b", "text": "9960 Hz signal", "correct": false}, {"id": "c", "text": "1020 Hz signal", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The impedance of an HF aerial is', '[{"id": "a", "text": "50 ohms", "correct": false}, {"id": "b", "text": "75 ohms", "correct": false}, {"id": "c", "text": "dependent on frequency", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The VHF aeronautical emergency frequency is', '[{"id": "a", "text": "125.5 MHz", "correct": false}, {"id": "b", "text": "121.5 MHz", "correct": true}, {"id": "c", "text": "121.0 MHz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On an RMI the input to the ADF pointer is fed via', '[{"id": "a", "text": "a differential synchro", "correct": false}, {"id": "b", "text": "a synchro", "correct": true}, {"id": "c", "text": "a matching unit", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Full scale deflection on a VOR system is', '[{"id": "a", "text": "2 degrees", "correct": false}, {"id": "b", "text": "5 degrees", "correct": false}, {"id": "c", "text": "10 degrees", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A VHF comm blade aerial has a length of', '[{"id": "a", "text": "a quarter wavelength", "correct": true}, {"id": "b", "text": "a half wavelength", "correct": false}, {"id": "c", "text": "a full wavelength", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Doppler VOR, when received by a conventional VOR receiver', '[{"id": "a", "text": "has normal reception but no ident signal", "correct": false}, {"id": "b", "text": "has normal reception with an ident signal", "correct": true}, {"id": "c", "text": "can not be received on CVOR equipment", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'At resonance in a series tuned circuit the impedance is', '[{"id": "a", "text": "low.", "correct": true}, {"id": "b", "text": "high.", "correct": false}, {"id": "c", "text": "reactive.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A mode `S` transponder utilises a', '[{"id": "a", "text": "linear amplifier", "correct": true}, {"id": "b", "text": "logarithmic amplifier", "correct": false}, {"id": "c", "text": "Darlington pair", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'What is the main cause of standing waves in waveguide?', '[{"id": "a", "text": "Mismatch of impedances", "correct": true}, {"id": "b", "text": "The frequency transmitted is too high", "correct": false}, {"id": "c", "text": "The velocity of propagation is too high", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The code in an altitude reporting system uses', '[{"id": "a", "text": "all C pulses together", "correct": false}, {"id": "b", "text": "at least one C pulse", "correct": true}, {"id": "c", "text": "C1 and C4 pulses together", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a secondary radar system at what frequency does the interrogator transmit on?', '[{"id": "a", "text": "1090MHz", "correct": false}, {"id": "b", "text": "1030MHz", "correct": true}, {"id": "c", "text": "1090KHz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In the OBS the printing report system is activated:', '[{"id": "a", "text": "Manually", "correct": false}, {"id": "b", "text": "Automatically", "correct": false}, {"id": "c", "text": "Both of the above", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In the downlink 11 format a 0.5 per sec pulse in the first half of the slot represents a logic', '[{"id": "a", "text": "a logic one", "correct": true}, {"id": "b", "text": "a logic zero", "correct": false}, {"id": "c", "text": "the start of the preamble", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The uplink 11 format utilises', '[{"id": "a", "text": "Differential Phase Shift Keying", "correct": true}, {"id": "b", "text": "Pulse Position Monitoring", "correct": false}, {"id": "c", "text": "Mono-pulse Dual Interrogation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a universal all-call transponder interrogation P2 is radiated by the', '[{"id": "a", "text": "Omni-directional aerial", "correct": true}, {"id": "b", "text": "Directional aerial", "correct": false}, {"id": "c", "text": "Horizontal dipole", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Group countdown in a transponder receiver changes the', '[{"id": "a", "text": "Selectivity", "correct": false}, {"id": "b", "text": "Sensitivity", "correct": true}, {"id": "c", "text": "Fidelity", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'T.C.A.S considers another aircraft to be on the ground at a difference height between the barometric altimeter and rad/alt of', '[{"id": "a", "text": "200ft", "correct": true}, {"id": "b", "text": "160ft", "correct": false}, {"id": "c", "text": "180ft", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'ACARS is used to transmit', '[{"id": "a", "text": "in Flight", "correct": false}, {"id": "b", "text": "on the ground", "correct": false}, {"id": "c", "text": "both of the above", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A Class 3 fault reporting failure', '[{"id": "a", "text": "may have an operational consequence", "correct": false}, {"id": "b", "text": "does not have an operational consequence but may do if a second failure occurs", "correct": false}, {"id": "c", "text": "has no consequences on aircraft safety", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Audio frequency range is', '[{"id": "a", "text": "20 to 2000 Hz", "correct": false}, {"id": "b", "text": "20 to 20,000 Hz", "correct": true}, {"id": "c", "text": "20 to 200,000 Hz", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An engine vibration indicator system uses', '[{"id": "a", "text": "AC/DC in the indicator", "correct": false}, {"id": "b", "text": "2 filters in the indicator", "correct": true}, {"id": "c", "text": "AC/DC in the transmitter", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GCU power derives its power supply from', '[{"id": "a", "text": "AC/DC power supplies", "correct": false}, {"id": "b", "text": "generator`s own supply", "correct": false}, {"id": "c", "text": "initially a trickle voltage from the permanent magnet", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'GCU is reset', '[{"id": "a", "text": "manually", "correct": true}, {"id": "b", "text": "by engine shut down restart", "correct": false}, {"id": "c", "text": "automatically", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'turn and slip needle/pointer moves to the left what is the aircraft doing', '[{"id": "a", "text": "turning left", "correct": true}, {"id": "b", "text": "rolling left", "correct": false}, {"id": "c", "text": "turning right", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Alpha floor protection to the autothrottle will', '[{"id": "a", "text": "withdraw flaps", "correct": false}, {"id": "b", "text": "increase speed", "correct": true}, {"id": "c", "text": "increase angle of attack", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Throttle hold will occur', '[{"id": "a", "text": "with weight on wheels", "correct": false}, {"id": "b", "text": "at the beginning of the take-off run", "correct": false}, {"id": "c", "text": "at a predetermined take-off speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An autopilot transfer valve', '[{"id": "a", "text": "converts hydraulic power to electrical power", "correct": false}, {"id": "b", "text": "converts electrical power to hydraulic power", "correct": true}, {"id": "c", "text": "converts hydraulic power to electrical power and converts electrical power to hydraulic powe", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The autothrottle controls the aircraft', '[{"id": "a", "text": "vertically", "correct": true}, {"id": "b", "text": "laterally", "correct": false}, {"id": "c", "text": "both later ally and vertically", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Speed information to the autothrottle is derived from', '[{"id": "a", "text": "the CADC", "correct": true}, {"id": "b", "text": "the IRS", "correct": false}, {"id": "c", "text": "the DME", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On replacement of an actuator that incorporates an autopilot actuator, the autopilot must be checked for', '[{"id": "a", "text": "correct sense of movement", "correct": false}, {"id": "b", "text": "correct sense and range of movement", "correct": false}, {"id": "c", "text": "correct sense and range of movement and autopilot breakout checks", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'On replacement of an autopilot servo motor', '[{"id": "a", "text": "position feedback must be checked", "correct": false}, {"id": "b", "text": "elevator and aileron must be checked", "correct": false}, {"id": "c", "text": "torque limiting settings must be checked", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The autopilot prevents adverse yaw by', '[{"id": "a", "text": "aileron to rudder cross feed", "correct": true}, {"id": "b", "text": "rudder to aileron cross feed", "correct": false}, {"id": "c", "text": "rudder to pitch cross feed", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The frequency of dutch roll oscillations are', '[{"id": "a", "text": "high", "correct": false}, {"id": "b", "text": "medium", "correct": true}, {"id": "c", "text": "low", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A series yaw damper', '[{"id": "a", "text": "moves the rudder only", "correct": true}, {"id": "b", "text": "moves ailerons and rudder", "correct": false}, {"id": "c", "text": "moves the rudder and the rudder pedals", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The purpose of a yaw damper is to prevent', '[{"id": "a", "text": "loss of height in a turn", "correct": false}, {"id": "b", "text": "adverse yaw", "correct": false}, {"id": "c", "text": "dutch roll", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An automatic disengagement of an autopilot will cause', '[{"id": "a", "text": "a red warning light to illuminate", "correct": false}, {"id": "b", "text": "a red warning light to illuminate and an aural warning", "correct": true}, {"id": "c", "text": "an aural warning only", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mach trimming is initiated by an input signal from', '[{"id": "a", "text": "CADC", "correct": true}, {"id": "b", "text": "IRS", "correct": false}, {"id": "c", "text": "Vertical gyro", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Mach trim prevents', '[{"id": "a", "text": "the nose dropping in a low speed turn", "correct": false}, {"id": "b", "text": "the nose lifting at high speed", "correct": false}, {"id": "c", "text": "the nose dropping at high speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Auto trimming trims the aircraft by', '[{"id": "a", "text": "moving the leading edge of the stabiliser", "correct": true}, {"id": "b", "text": "movement of the elevator", "correct": false}, {"id": "c", "text": "movement of either the elevator or the stabiliser", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Automatic trimming starts on the detection of', '[{"id": "a", "text": "loss of position feedback", "correct": false}, {"id": "b", "text": "standing load on the elevator", "correct": true}, {"id": "c", "text": "loss of servo input", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An autopilot runaway is prevented by', '[{"id": "a", "text": "position feedback", "correct": false}, {"id": "b", "text": "a fuse", "correct": false}, {"id": "c", "text": "torque limiting devise", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'An autopilot hardover runaway is caused by', '[{"id": "a", "text": "loss of position feedback", "correct": true}, {"id": "b", "text": "loss of servo power supply", "correct": false}, {"id": "c", "text": "loss of clutch supply", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'Inner loop servo control of an autopilot will provide', '[{"id": "a", "text": "stability and navigation commands", "correct": false}, {"id": "b", "text": "navigation commands only", "correct": false}, {"id": "c", "text": "stability only", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'A signal at 120 MHz freq will normally propagate by means of', '[{"id": "a", "text": "ground waves", "correct": false}, {"id": "b", "text": "sky waves", "correct": false}, {"id": "c", "text": "space waves", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'The length of a resonant antenna dipole is', '[{"id": "a", "text": "lambda", "correct": false}, {"id": "b", "text": "lambda/2", "correct": true}, {"id": "c", "text": "lambda/4", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In a vertically polarized electromagnetic wave', '[{"id": "a", "text": "the electric field vectors are vertical", "correct": true}, {"id": "b", "text": "the magnetic field vectors are vertical", "correct": false}, {"id": "c", "text": "both electric and magnetic are vertical", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M13.23'), 'In yagi-array antenna, the signal is fed through a cable to', '[{"id": "a", "text": "dipole", "correct": true}, {"id": "b", "text": "parasitic elements", "correct": false}, {"id": "c", "text": "both", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'From where is manifold pressure taken on a supercharged engine?', '[{"id": "a", "text": "Between the carburetor and the supercharger", "correct": false}, {"id": "b", "text": "Between the supercharger and the throttle", "correct": true}, {"id": "c", "text": "Between the carburetor and the induction ports", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'on a gas turbine engine, what is the fan driven by?', '[{"id": "a", "text": "HP turbine", "correct": false}, {"id": "b", "text": "LP turbine", "correct": true}, {"id": "c", "text": "IP turbine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What is an engine stage?', '[{"id": "a", "text": "One rotor plus one stator", "correct": true}, {"id": "b", "text": "One IGV and one rotor", "correct": false}, {"id": "c", "text": "One compressor rotor and one nozzle guide vane", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The air data input to the FADEC fails. The result will be', '[{"id": "a", "text": "a lack of flight data", "correct": false}, {"id": "b", "text": "uncorrected data from hard wired analogue sensors is utilized", "correct": true}, {"id": "c", "text": "the FADEC reverts to the failsafe mode", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Torque measurement is taken from the', '[{"id": "a", "text": "free turbine shaft", "correct": false}, {"id": "b", "text": "reduction gearbox", "correct": true}, {"id": "c", "text": "prop shaft", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A FADEC system consists of', '[{"id": "a", "text": "HMU, sensors and an EEC", "correct": true}, {"id": "b", "text": "HMU, ADC and sensors", "correct": false}, {"id": "c", "text": "EEC, ADC and sensors", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What power supply is required for a thermocouple system to work?', '[{"id": "a", "text": "Direct current", "correct": false}, {"id": "b", "text": "Alternating current", "correct": false}, {"id": "c", "text": "Neither of the above", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a 24 thermocouple system, one thermocouple goes open circuit. What error is detected at the indicator?', '[{"id": "a", "text": "None", "correct": true}, {"id": "b", "text": "No indication", "correct": false}, {"id": "c", "text": "Gauge freezes at last known reading", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a thermocouple temperature sensing system, what is the purpose of the compensating resistor?', '[{"id": "a", "text": "To correct for varying ambient temperatures at the hot junction", "correct": false}, {"id": "b", "text": "To correct for varying ambient temperatures at the cold junction", "correct": true}, {"id": "c", "text": "To standardize the reading for different engine types", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a dive, with the throttles fixed, the EPR will', '[{"id": "a", "text": "increase", "correct": false}, {"id": "b", "text": "decrease", "correct": true}, {"id": "c", "text": "not change", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'How is the N1 and N2 measured on a triple spool engine?', '[{"id": "a", "text": "Pulse type speed probes", "correct": true}, {"id": "b", "text": "Tachometer connected to the external gearbox", "correct": false}, {"id": "c", "text": "Tachometer connected to the internal gearbox", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A twin spool engine has', '[{"id": "a", "text": "one turbine on one shaft", "correct": false}, {"id": "b", "text": "two turbines on one shaft", "correct": false}, {"id": "c", "text": "two turbines on two shafts", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A free turbine aircraft engine is most likely to be used on a', '[{"id": "a", "text": "high bypass engine", "correct": false}, {"id": "b", "text": "a direct coupled engine", "correct": false}, {"id": "c", "text": "a helicopter engine", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Propeller speed is measured from', '[{"id": "a", "text": "a slip ring pulse probe", "correct": true}, {"id": "b", "text": "a tachometer on the LP turbine shaft", "correct": false}, {"id": "c", "text": "a pulse probe at the engine side of the reduction gear", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Propeller torque is analogous to', '[{"id": "a", "text": "engine RPM", "correct": false}, {"id": "b", "text": "shaft horsepower", "correct": true}, {"id": "c", "text": "propeller RPM", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'How is power indicated on a fixed pitch propeller?', '[{"id": "a", "text": "RPM gauge", "correct": true}, {"id": "b", "text": "Torque gauge", "correct": false}, {"id": "c", "text": "Horsepower gauge", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What are the units of manifold pressure on a normally aspirated engine?', '[{"id": "a", "text": "PSI", "correct": false}, {"id": "b", "text": "Inches of water", "correct": false}, {"id": "c", "text": "Inches of mercury", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a FADEC what is the result of Channel A failing to receive information from a sensor?', '[{"id": "a", "text": "Channel B will assume control", "correct": false}, {"id": "b", "text": "Channel A will take the information from channel B", "correct": true}, {"id": "c", "text": "Channel A will take the information from the backup sensor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A synchro pressure measuring system requires', '[{"id": "a", "text": "alternating current", "correct": true}, {"id": "b", "text": "direct current", "correct": false}, {"id": "c", "text": "either ac or dc", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A synchro pressure measuring system works on the principle of changes in pressure related to changes in', '[{"id": "a", "text": "frequency", "correct": false}, {"id": "b", "text": "voltage", "correct": false}, {"id": "c", "text": "flux", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Pure jet engines use', '[{"id": "a", "text": "stagnation thermocouples", "correct": true}, {"id": "b", "text": "rapid response", "correct": false}, {"id": "c", "text": "variable resistance thermocouples", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Modern oil pressure servo transmitters sense', '[{"id": "a", "text": "differential pressure", "correct": true}, {"id": "b", "text": "absolute pressure", "correct": false}, {"id": "c", "text": "HP oil pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'EGT thermocouples are usually made of', '[{"id": "a", "text": "nickel and platinum", "correct": false}, {"id": "b", "text": "chromel and platinum", "correct": false}, {"id": "c", "text": "chromel and alumel", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Thrust is generated in a turboprop system by', '[{"id": "a", "text": "moving a small mass of air quickly", "correct": false}, {"id": "b", "text": "moving a large mass of air quickly", "correct": false}, {"id": "c", "text": "moving a large mass of air slowly", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Power is adjusted in a variable pitch turboprop aircraft by', '[{"id": "a", "text": "increasing RPM", "correct": false}, {"id": "b", "text": "increasing fuel flow", "correct": true}, {"id": "c", "text": "increasing pitch", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Thrust in a high bypass engine is measured by measuring', '[{"id": "a", "text": "N3 RPM", "correct": false}, {"id": "b", "text": "fuel flow", "correct": false}, {"id": "c", "text": "neither of the above, thrust is not indicated in flight", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'EPR is a ratio of', '[{"id": "a", "text": "P1 to P4", "correct": false}, {"id": "b", "text": "P1 to Pfan", "correct": false}, {"id": "c", "text": "P1 to P6", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The majority of power in a free turbine engine is used to', '[{"id": "a", "text": "drive the gas generator", "correct": false}, {"id": "b", "text": "drive the free turbine", "correct": true}, {"id": "c", "text": "expel gases through the exhaust", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The total power in a turboprop engine is the', '[{"id": "a", "text": "SHP", "correct": true}, {"id": "b", "text": "ESHP", "correct": false}, {"id": "c", "text": "BHP", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'To measure oil temperature, which of the following would most likely be used?', '[{"id": "a", "text": "Resistance temperature measurement", "correct": true}, {"id": "b", "text": "Thermocouple measurement", "correct": false}, {"id": "c", "text": "Optical pyrometer", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Strain gauges may be used to measure', '[{"id": "a", "text": "thrust", "correct": false}, {"id": "b", "text": "torque", "correct": true}, {"id": "c", "text": "pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Piezo electric transducers convert', '[{"id": "a", "text": "a tensile stress into a current output", "correct": false}, {"id": "b", "text": "a pressure input into a resistance output", "correct": false}, {"id": "c", "text": "a force input into a voltage output", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A broadband vibration reading indicates', '[{"id": "a", "text": "the N1 vibration", "correct": false}, {"id": "b", "text": "the average vibration", "correct": true}, {"id": "c", "text": "the peak allowable vibration", "correct": false}]'::jsonb, '{B2}'),
