    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An annular combustion chamber consists of', '[{"id": "a", "text": "an air tube and a flame tube", "correct": false}, {"id": "b", "text": "an outer skin and an inner and outer flame skin", "correct": true}, {"id": "c", "text": "a series of flame tube in an air annulus", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A full flow oil system has', '[{"id": "a", "text": "a single fixed minimum oil pressure", "correct": false}, {"id": "b", "text": "a hot and cold oil pressure limit", "correct": false}, {"id": "c", "text": "a variable oil pressure dependant upon throttle setting", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Oil quantity is transmitted to the EICAS by', '[{"id": "a", "text": "a float switch in the oil tank", "correct": false}, {"id": "b", "text": "a reed switch ladder activated by magnetic float in the oil tank", "correct": true}, {"id": "c", "text": "a belt type capacitor system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Thrust in a high bypass fan engine is indicated by', '[{"id": "a", "text": "N1 RPM or EPR", "correct": true}, {"id": "b", "text": "N3 RPM or P1/P4 ratio", "correct": false}, {"id": "c", "text": "N1 RPM or N3 RPM", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The purpose of the LP fuel pump is to', '[{"id": "a", "text": "ensure the fuel flow governor gets enough fuel", "correct": false}, {"id": "b", "text": "pump fuel from the aircraft fuel tanks to the engine", "correct": false}, {"id": "c", "text": "ensure the HP fuel pump does not cavitate", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The principle of operation of a DC ratio meter is', '[{"id": "a", "text": "one coil moving in a uniform magnetic field", "correct": false}, {"id": "b", "text": "two coils moving in a uniform magnetic field", "correct": false}, {"id": "c", "text": "two coils moving in a non-uniform magnetic field", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A thermocouple indicator is basically a', '[{"id": "a", "text": "millivoltmeter", "correct": true}, {"id": "b", "text": "milliohmeter", "correct": false}, {"id": "c", "text": "milliameter", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'If a FADEC loses its ADC input, in the short term it will', '[{"id": "a", "text": "go into soft redundancy", "correct": true}, {"id": "b", "text": "go into hard redundancy", "correct": false}, {"id": "c", "text": "go to limit protection mode", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'With an aircraft with a fixed pitch propeller, what indication has the pilot got of the output power?', '[{"id": "a", "text": "fuel flow", "correct": false}, {"id": "b", "text": "oil pressure", "correct": false}, {"id": "c", "text": "engine speed indicator", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The primary purpose of an EEC is', '[{"id": "a", "text": "to change analogue inputs into digital format to provide glass cockpit information and reduce flight", "correct": false}, {"id": "b", "text": "to change analogue inputs into digital format to reduce flight crew workload and provide", "correct": false}, {"id": "c", "text": "to save fuel, reduce crew workload and reduce maintenance costs", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'If a tachogenerator indicated in reverse, the probable cause is', '[{"id": "a", "text": "wrong input frequency", "correct": false}, {"id": "b", "text": "two phases cross connected", "correct": true}, {"id": "c", "text": "supply and transmitter cross connected", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A sensing element goes open circuit in a ratiometer. What will be happen?', '[{"id": "a", "text": "Temperature indicates below ambient", "correct": false}, {"id": "b", "text": "Full scale deflection", "correct": true}, {"id": "c", "text": "Hairspring takes indicator off scale", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A thermocouple is constructed of', '[{"id": "a", "text": "two dissimilar metals welded together", "correct": true}, {"id": "b", "text": "two dissimilar metals with an air gap between them", "correct": false}, {"id": "c", "text": "three dissimilar metals welded together", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A thermocouple indication is taken from the', '[{"id": "a", "text": "hot junction", "correct": false}, {"id": "b", "text": "cold junction", "correct": false}, {"id": "c", "text": "difference between the hot junction and the cold junction", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'On a twin spool engine, the HP compressor is driven by', '[{"id": "a", "text": "ram air over the compressor", "correct": false}, {"id": "b", "text": "early stages of the turbine", "correct": true}, {"id": "c", "text": "later stages of the turbine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a multiple probe thermocouple system, what is the effect if one probe fails?', '[{"id": "a", "text": "Increase in temp reading", "correct": false}, {"id": "b", "text": "Reduction in temp reading", "correct": false}, {"id": "c", "text": "No noticeable effect", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a gas turbine if air is tapped from the H.P bleed', '[{"id": "a", "text": "EPR decreases and EGT increases", "correct": true}, {"id": "b", "text": "EPR stays constant and EGT decreases", "correct": false}, {"id": "c", "text": "EPR increases and EGT decreases", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The vane on a vane type fuel flow measuring device becomes stuck. What safety backup is available for the engine fuel flow?', '[{"id": "a", "text": "A fuel bleed valve", "correct": false}, {"id": "b", "text": "A bypass valve", "correct": false}, {"id": "c", "text": "A differential pressure bypass valve", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a FADEC engine with a hydromechanical fuel system, how is fuel flow controlled?', '[{"id": "a", "text": "By fuel pressure", "correct": false}, {"id": "b", "text": "By electro-hydraulic servo valves (EHSVs)", "correct": true}, {"id": "c", "text": "By oil hydraulics", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In the HEIU the discharge resistor', '[{"id": "a", "text": "allows sufficient voltage to be stored to provide relight facilities", "correct": false}, {"id": "b", "text": "protects the unit from excessive voltages.", "correct": false}, {"id": "c", "text": "allows the capacitors to discharge when the unit is switched off.", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A modular constructed gas turbine engine means that', '[{"id": "a", "text": "its major assemblies can be removed and replaced", "correct": true}, {"id": "b", "text": "all engines have a specific component layout", "correct": false}, {"id": "c", "text": "the engine is constructed by the vertical assembly technique", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The purpose of a high pypass ducted fan engine is to', '[{"id": "a", "text": "improve efficiency", "correct": true}, {"id": "b", "text": "improve thrust", "correct": false}, {"id": "c", "text": "reduce size", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'When using a test set to test an EGT thermocouple circuit', '[{"id": "a", "text": "no compensation for ambient temperature is required", "correct": true}, {"id": "b", "text": "only consider ambient temperature compensation if the ambient temperature is over 20oC", "correct": false}, {"id": "c", "text": "always compensate for ambient temperature", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Where is EGT measured?', '[{"id": "a", "text": "In the combustion chamber", "correct": false}, {"id": "b", "text": "Downstream of the combustion chamber", "correct": true}, {"id": "c", "text": "Upstream of the combustion chamber", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'How does a boost gauge compensate for altitude changes?', '[{"id": "a", "text": "Spring sealed bellows", "correct": true}, {"id": "b", "text": "Two bellows against atmospheric pressure", "correct": false}, {"id": "c", "text": "There is no compensation", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An EMF is produced by a thermocouple. This is sensed', '[{"id": "a", "text": "at the hot junction", "correct": false}, {"id": "b", "text": "at the cold junction", "correct": false}, {"id": "c", "text": "between the hot and cold junctions", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Supervisory EEC sends its output to the', '[{"id": "a", "text": "fuel valve", "correct": false}, {"id": "b", "text": "HMU/FFG", "correct": true}, {"id": "c", "text": "EGT thermocouple circuit", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Ratiometer pointer movement is achieved by', '[{"id": "a", "text": "one coil providing a torque against a permanent magnet", "correct": false}, {"id": "b", "text": "two opposing coils providing a torque in a varying magnetic field", "correct": false}, {"id": "c", "text": "two opposing coils providing a torque in a permanent magnetic field", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A fuel flow transmitter requires a motor or a synchronous motor to have a', '[{"id": "a", "text": "constant voltage within small tolerances", "correct": false}, {"id": "b", "text": "constant frequency within small tolerances", "correct": true}, {"id": "c", "text": "low EMF as it is immersed in fuel", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A boost gauge measures', '[{"id": "a", "text": "absolute pressure on the inlet port", "correct": true}, {"id": "b", "text": "brake mean effective pressure", "correct": false}, {"id": "c", "text": "gauge pressure at the injector", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'On a thermocouple circuit on a non FADEC engine, what is the purpose of the ballast resistor?', '[{"id": "a", "text": "To compensate for ambient temperatures", "correct": false}, {"id": "b", "text": "To standardise both engine`s EGT readings", "correct": true}, {"id": "c", "text": "To compensate for altitude", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Boost pressure is measured in', '[{"id": "a", "text": "inches of Hg", "correct": true}, {"id": "b", "text": "inches of water", "correct": false}, {"id": "c", "text": "PSI", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Power is adjusted in a gas turbine engine by', '[{"id": "a", "text": "increasing airflow to the combustion chamber", "correct": false}, {"id": "b", "text": "increasing air and fuel flow", "correct": false}, {"id": "c", "text": "increasing fuel flow", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The EPR reading is taken from a ratio of', '[{"id": "a", "text": "jet pipe pressure to compressor inlet pressure", "correct": true}, {"id": "b", "text": "compressor delivery pressure to compressor inlet pressure", "correct": false}, {"id": "c", "text": "turbine inlet pressure to compressor delivery pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The basic gas turbine engine cycle is', '[{"id": "a", "text": "induction, compression, combustion, expansion, exhaust", "correct": true}, {"id": "b", "text": "induction, compression, expansion, combustion, exhaust", "correct": false}, {"id": "c", "text": "compression, combustion, induction, expansion, exhaust", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The high bypass duct', '[{"id": "a", "text": "drives a cabin air compressor", "correct": false}, {"id": "b", "text": "provides engine cooling", "correct": false}, {"id": "c", "text": "improves propulsive efficiency", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'If an engines fadec system loses air data permanently the pilot will', '[{"id": "a", "text": "select alternate pitot static", "correct": true}, {"id": "b", "text": "switch to alt on the relevent EEC", "correct": false}, {"id": "c", "text": "turn that EEC off", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An EPR system reads slightly over 1, this would mean', '[{"id": "a", "text": "the transmitter datum point has moved and needs replacing", "correct": false}, {"id": "b", "text": "no action required this is normal", "correct": true}, {"id": "c", "text": "the indicator needs re-calibrating back to 1", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Manifold pressure is measured', '[{"id": "a", "text": "at inlet port above and below ambient conditions", "correct": true}, {"id": "b", "text": "at inlet port above and below standard atmosphere at sea level", "correct": false}, {"id": "c", "text": "at inlet port indicating boost pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A temperature indicating system incorporating a resistance bulb on a selected range has pointer movement', '[{"id": "a", "text": "proportional to bulb resistance", "correct": true}, {"id": "b", "text": "inversely proportional to bulb resistance", "correct": false}, {"id": "c", "text": "resistance does not affect pointer movement", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a ducted fan engine, the fan is driven by the', '[{"id": "a", "text": "accessory gearbox", "correct": false}, {"id": "b", "text": "turbine", "correct": true}, {"id": "c", "text": "air passing over the compressor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a FADEC system, active control switchover occurs', '[{"id": "a", "text": "on engine startup only.", "correct": true}, {"id": "b", "text": "when channels A and B are healthy.", "correct": false}, {"id": "c", "text": "on shutdown.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Gas turbines work on the', '[{"id": "a", "text": "otto cycle", "correct": false}, {"id": "b", "text": "brayton cycle", "correct": true}, {"id": "c", "text": "diesel cycle", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Oil systems consists of', '[{"id": "a", "text": "2 systems", "correct": false}, {"id": "b", "text": "3 systems", "correct": true}, {"id": "c", "text": "4 systems", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'With the EEC in control the throttle levers are always', '[{"id": "a", "text": "in the fully forward position", "correct": false}, {"id": "b", "text": "in the fully aft position", "correct": false}, {"id": "c", "text": "anywhere between the fully fwd and fully aft positions", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Turboprop thermocouple probes are', '[{"id": "a", "text": "rapid response", "correct": true}, {"id": "b", "text": "stagnation", "correct": false}, {"id": "c", "text": "surface mounted", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Propelling nozzle provide', '[{"id": "a", "text": "pressure thrust", "correct": false}, {"id": "b", "text": "velocity thrust", "correct": true}, {"id": "c", "text": "pressure and velocity thrust", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'How are the combustion chambers cooled?', '[{"id": "a", "text": "By l.p compressor air", "correct": false}, {"id": "b", "text": "By h.p compressor air", "correct": true}, {"id": "c", "text": "By fan pressure air", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Fan blade speed is measured by', '[{"id": "a", "text": "phonic wheel", "correct": true}, {"id": "b", "text": "drag cup and tachometer", "correct": false}, {"id": "c", "text": "eddy currents", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Fadecs operate by', '[{"id": "a", "text": "2 controlling 1 operating", "correct": false}, {"id": "b", "text": "1 controlling 1 operating", "correct": false}, {"id": "c", "text": "2 units each capable of independent control", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'When a thermocouple fails, the temperature reading will', '[{"id": "a", "text": "over read", "correct": false}, {"id": "b", "text": "under read", "correct": true}, {"id": "c", "text": "stay the same", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An aircraft flying at 800mph would typically use', '[{"id": "a", "text": "turbojet", "correct": true}, {"id": "b", "text": "turbofan", "correct": false}, {"id": "c", "text": "turboprop", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The inlet of a turbo fan is', '[{"id": "a", "text": "divergent", "correct": true}, {"id": "b", "text": "convergent", "correct": false}, {"id": "c", "text": "convergent-divergent", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What is the pressure increase over one stage of a centrifugal compressor?', '[{"id": "a", "text": "5:1", "correct": true}, {"id": "b", "text": "1.2:1", "correct": false}, {"id": "c", "text": "8:1", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The bleed valve on a engine at start up is', '[{"id": "a", "text": "open", "correct": true}, {"id": "b", "text": "closed", "correct": false}, {"id": "c", "text": "modulating", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'EPR is measured between inlet and', '[{"id": "a", "text": "jet pipe", "correct": true}, {"id": "b", "text": "cold and hot exhaust", "correct": false}, {"id": "c", "text": "front of turbine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'One stage of a turbine is', '[{"id": "a", "text": "n.g.v then turbine blade", "correct": true}, {"id": "b", "text": "turbine blade then n.g.v", "correct": false}, {"id": "c", "text": "i.g.v then turbine blade", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'in a flow type fuel system, fuel shutoff is done by', '[{"id": "a", "text": "mechanical ball valve", "correct": true}, {"id": "b", "text": "fcu torque motor", "correct": false}, {"id": "c", "text": "l.p fuel cock", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The fuel flow transmitter is downstream of', '[{"id": "a", "text": "prsov", "correct": false}, {"id": "b", "text": "h.p pump", "correct": false}, {"id": "c", "text": "l.p pump", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'How is fuel flow varied in a variable displacement pressure type pump?', '[{"id": "a", "text": "Alter the camplate angle", "correct": true}, {"id": "b", "text": "Remote servo pressure", "correct": false}, {"id": "c", "text": "Direct cable to camplate", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'When the full authority fuel control unit is changed, the rating plug', '[{"id": "a", "text": "stays with the engine", "correct": true}, {"id": "b", "text": "stays with the FAFC", "correct": false}, {"id": "c", "text": "is replaced every time", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The EEC is powered and able to operate via', '[{"id": "a", "text": "only a dedicated alternator", "correct": false}, {"id": "b", "text": "the aircraft electrical system", "correct": false}, {"id": "c", "text": "The EEC is capable of being powered by both independently depending on conditions", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The EEC uses', '[{"id": "a", "text": "ARINC 429 formatted data", "correct": true}, {"id": "b", "text": "ARINC 629 formatted data", "correct": false}, {"id": "c", "text": "uses neither ARINC 429 or 629 formatted data", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The fuel metering unit has direct inputs via', '[{"id": "a", "text": "only the EEC", "correct": false}, {"id": "b", "text": "the EEC and the fire control handle", "correct": false}, {"id": "c", "text": "the EEC, fire control handle and the engine master switch", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The optimum turbine speed is defined as', '[{"id": "a", "text": "the most efficient speed of the turbine", "correct": true}, {"id": "b", "text": "100% rpm of the engine", "correct": false}, {"id": "c", "text": "95 % rpm of the engine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An increase in fuel flow through the impeller type fuel flow transmitter is measured by', '[{"id": "a", "text": "drum lags impeller", "correct": false}, {"id": "b", "text": "impeller lags turbine", "correct": true}, {"id": "c", "text": "decreasing angle between the two", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'No power to EGT is indicated by', '[{"id": "a", "text": "yellow flag in front counter", "correct": true}, {"id": "b", "text": "bug moves in the x direction", "correct": false}, {"id": "c", "text": "bug moves in the y direction", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Connection to a tachogenerator', '[{"id": "a", "text": "3 phase star", "correct": true}, {"id": "b", "text": "3 phase delta", "correct": false}, {"id": "c", "text": "2 phase star", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A short circuit in a d.c ratiometer will give', '[{"id": "a", "text": "max scale reading", "correct": false}, {"id": "b", "text": "zero scale reading", "correct": false}, {"id": "c", "text": "min scale reading", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An open circuit in a d.c ratiometer will give', '[{"id": "a", "text": "max scale reading", "correct": true}, {"id": "b", "text": "zero scale reading", "correct": false}, {"id": "c", "text": "min scale reading", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A compressor shaft rotates on', '[{"id": "a", "text": "sintered bearings", "correct": false}, {"id": "b", "text": "ball and roller bearings", "correct": true}, {"id": "c", "text": "plain bearings", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The EEC changes power settings by', '[{"id": "a", "text": "changing the throttle lever angle", "correct": false}, {"id": "b", "text": "changing the fuel flow input", "correct": true}, {"id": "c", "text": "changing the airflow input", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A torque pressure measuring indicator is fed by', '[{"id": "a", "text": "direct oil pressure", "correct": true}, {"id": "b", "text": "differential pneumatic pressure", "correct": false}, {"id": "c", "text": "servo operated", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The tacho generator output has:', '[{"id": "a", "text": "A fixed frequency", "correct": false}, {"id": "b", "text": "A Variable frequency", "correct": true}, {"id": "c", "text": "A DC Current output", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'On a fuel flow measuring device located on the engine', '[{"id": "a", "text": "no adjustments can be made", "correct": true}, {"id": "b", "text": "external adjustments can be made for maximum rate fuel flow", "correct": false}, {"id": "c", "text": "external adjustments can be made for minimum rate fuel flow", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Where is the hot junction of a EGT thermocouple system found?', '[{"id": "a", "text": "In the indicator", "correct": false}, {"id": "b", "text": "Upstream of the combustion chamber", "correct": false}, {"id": "c", "text": "Downstream of the combustion chamber", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The fan on a turbofan engine is turned by', '[{"id": "a", "text": "induction of the air across the fan into the compressor", "correct": false}, {"id": "b", "text": "the turbine section", "correct": true}, {"id": "c", "text": "the combustion chamber gases", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'When terminating connections for a EGT sensing system', '[{"id": "a", "text": "ensure that the pins and sockets are correctly crimped and brazed", "correct": false}, {"id": "b", "text": "ensure that all connections are silver soldered", "correct": false}, {"id": "c", "text": "ensure that the pins and sockets are of the same material as the leads", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'An EPR gauge indicates `1`. You should', '[{"id": "a", "text": "adjust the indicator back to zero", "correct": false}, {"id": "b", "text": "replace the indicator, there is no adjustment", "correct": false}, {"id": "c", "text": "do nothing this is what it should read with the engine shut down.", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A Gas Turbine`s propulsion force is produced by', '[{"id": "a", "text": "reaction of the rearward moving gasses", "correct": true}, {"id": "b", "text": "impingement of the gasses on the surrounding air", "correct": false}, {"id": "c", "text": "induced airflow into the engine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a single spool gas turbine engine the compressor rev/min is', '[{"id": "a", "text": "more than the turbine speed", "correct": false}, {"id": "b", "text": "less than the turbine speed", "correct": false}, {"id": "c", "text": "equal to the turbine speed", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A tacho pointer is moved by', '[{"id": "a", "text": "drag cup coupling", "correct": true}, {"id": "b", "text": "ac servo motor", "correct": false}, {"id": "c", "text": "synchronous motor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a twin spool engine', '[{"id": "a", "text": "the HP turbine drives both LP and HP compressors", "correct": false}, {"id": "b", "text": "the LP turbine drives the LP compressor and the HP turbine drives the HP compressor", "correct": true}, {"id": "c", "text": "the HP turbine drives the LP compressor and the LP turbine drives the HP compressor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Relative permeability of fuel is also known as', '[{"id": "a", "text": "density of the fuel", "correct": false}, {"id": "b", "text": "weight of the fuel", "correct": false}, {"id": "c", "text": "dielectric constant of the fuel", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The cycle of a gas turbine engine is', '[{"id": "a", "text": "completed in one revolution of engine.", "correct": false}, {"id": "b", "text": "completed in two revolution of the engine.", "correct": false}, {"id": "c", "text": "continuous", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Engines having two independent moving systems are', '[{"id": "a", "text": "compound engines", "correct": false}, {"id": "b", "text": "twin spool engines", "correct": true}, {"id": "c", "text": "complex engines", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Compression ratio of compressor of gas turbine Engine is', '[{"id": "a", "text": "outlet pressure to Inlet pressure.", "correct": true}, {"id": "b", "text": "measured across all rotor stages of compressor", "correct": false}, {"id": "c", "text": "mass of airflow to combustion.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Torque pressure indication to measure power output of an engine is', '[{"id": "a", "text": "used in all Gas Turbine engines.", "correct": false}, {"id": "b", "text": "not used in Gas Turbine engines.", "correct": false}, {"id": "c", "text": "only used when engine output pressure is used for torque not for thrust.", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Manifold pressure is measured in', '[{"id": "a", "text": "direct absolute pressure in Bars", "correct": false}, {"id": "b", "text": "differential pressure in millibars", "correct": false}, {"id": "c", "text": "direct absolute pressure in inch of Hg", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Typically a torque pressure indication system is', '[{"id": "a", "text": "differential pressure type", "correct": true}, {"id": "b", "text": "remote synchronous type", "correct": false}, {"id": "c", "text": "direct Oil Pressure sensing type", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A tachometer used to measure Rev/Min in turbine engines', '[{"id": "a", "text": "develops its own power for the system", "correct": true}, {"id": "b", "text": "28V dc is required", "correct": false}, {"id": "c", "text": "115V ac is required", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Primary power for electronic engine control', '[{"id": "a", "text": "115V ac essential bus.", "correct": false}, {"id": "b", "text": "on side 115V ac bus bar supply.", "correct": false}, {"id": "c", "text": "Permanent Magnet Alternator", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Leads to measure thermocouple temperature are', '[{"id": "a", "text": "calibrated for circuit in used and cannot be shortened", "correct": true}, {"id": "b", "text": "affected by Magnetic and electrical interference", "correct": false}, {"id": "c", "text": "insulated by heat legging device to reduce errors in the indication end", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A thermocouple sensing system test set requires', '[{"id": "a", "text": "a serviceable battery", "correct": true}, {"id": "b", "text": "No power", "correct": false}, {"id": "c", "text": "24V dc", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The HP compressor is powered by', '[{"id": "a", "text": "the first set of turbines", "correct": true}, {"id": "b", "text": "the last set of turbines", "correct": false}, {"id": "c", "text": "the intermediate compressor", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Torque is measured in gas turbine engines', '[{"id": "a", "text": "never", "correct": false}, {"id": "b", "text": "where there is a free turbine providing the power", "correct": true}, {"id": "c", "text": "on small pure jet engines", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What is the supply voltage to tacho generators?', '[{"id": "a", "text": "28vdc", "correct": false}, {"id": "b", "text": "115vac", "correct": false}, {"id": "c", "text": "It has no supply", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A FADEC takes measurements of engine speed,', '[{"id": "a", "text": "temperature and pressure", "correct": true}, {"id": "b", "text": "temperature", "correct": false}, {"id": "c", "text": "pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The fuel metering valve in the hydro mechanical unit of a FADEC system is operated by', '[{"id": "a", "text": "hydraulic servo pressure", "correct": false}, {"id": "b", "text": "fuel servo pressure", "correct": true}, {"id": "c", "text": "electrical servo", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Boost pressure is', '[{"id": "a", "text": "atmospheric above ambient", "correct": false}, {"id": "b", "text": "atmospheric below ambient", "correct": false}, {"id": "c", "text": "the absolute of the manifold chamber", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'To check/test a temperature indicator you would', '[{"id": "a", "text": "connect a decade box in place of the temperature sensing element", "correct": true}, {"id": "b", "text": "connect a decade box in series with the temperature sensing element", "correct": false}, {"id": "c", "text": "connect a decade box in parallel with the temperature sensing element", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Calibration for a ratiometer type temperature indicator takes into account', '[{"id": "a", "text": "the material of the coils", "correct": false}, {"id": "b", "text": "the material of the sensing element", "correct": true}, {"id": "c", "text": "the type of representation on the dial", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Reverse thrust can only be selected when the throttle is', '[{"id": "a", "text": "75% power position.", "correct": false}, {"id": "b", "text": "open.", "correct": false}, {"id": "c", "text": "at the idle stop", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'On a FADEC engine the EEC', '[{"id": "a", "text": "has electronic control of the hydro-mechanical fuel control unit in all modes", "correct": true}, {"id": "b", "text": "has electronic control of the hydro-mechanical fuel control in some modes", "correct": false}, {"id": "c", "text": "has mechanical control of the hydro-mechanical fuel control system", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'EPR is a measure of', '[{"id": "a", "text": "exhaust pressure compared to compressor inlet pressure", "correct": true}, {"id": "b", "text": "exhaust pressure compared to combustor pressure", "correct": false}, {"id": "c", "text": "combustion pressure compared to compressor inlet pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What exactly does a thermocouple measure?', '[{"id": "a", "text": "The difference between the hot and cold junction.", "correct": true}, {"id": "b", "text": "Hot junction temperature.", "correct": false}, {"id": "c", "text": "Cold junction temperature.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'In a temperature sensing ratiometer what determines the actual temperature?', '[{"id": "a", "text": "The material of the sensor", "correct": true}, {"id": "b", "text": "The material of the sensing coil", "correct": false}, {"id": "c", "text": "The material of the balancing coil", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Torque is a useful measure', '[{"id": "a", "text": "on engines where a portion of thrust produces torque", "correct": true}, {"id": "b", "text": "on engines which only produce thrust", "correct": false}, {"id": "c", "text": "on all engines", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Boost pressure is a measure of', '[{"id": "a", "text": "manifold pressure", "correct": true}, {"id": "b", "text": "atmospheric pressure plus turbocharger inlet pressure", "correct": false}, {"id": "c", "text": "atmospheric pressure less turbocharger inlet pressure", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The test switch of a continuous loop fire detector gives a', '[{"id": "a", "text": "continuity check", "correct": true}, {"id": "b", "text": "bonding check", "correct": false}, {"id": "c", "text": "insulation check", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What are the types of continuous fire detection system?', '[{"id": "a", "text": "Capacitive and resistive", "correct": true}, {"id": "b", "text": "Capacitive", "correct": false}, {"id": "c", "text": "Inductive and capacitive", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'During normal running conditions', '[{"id": "a", "text": "combustion is continuously supported by ignition", "correct": false}, {"id": "b", "text": "combustion is intermittently supported by ignition", "correct": false}, {"id": "c", "text": "combustion is self supporting", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'What indication does the pilot receive that thrust reversers have deployed?', '[{"id": "a", "text": "A feeling of rapid deceleration", "correct": false}, {"id": "b", "text": "An audible warning", "correct": false}, {"id": "c", "text": "A sequence of lights", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'on a fixed pitch propeller single engine aircraft, what is indicated as a measure of power?', '[{"id": "a", "text": "Oil pressure", "correct": false}, {"id": "b", "text": "Engine speed", "correct": true}, {"id": "c", "text": "Cylinder head temperature", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'in a turbine engine used to drive a propeller, the power from the engine is', '[{"id": "a", "text": "majority for jet reaction and the residual to drive the prop", "correct": false}, {"id": "b", "text": "the majority of power is used to drive the prop, with the residual giving a jet reaction", "correct": true}, {"id": "c", "text": "the power is divided equally.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The term "Mass Flow" as used in a jet engine refers to', '[{"id": "a", "text": "total mass of air divided by time.", "correct": true}, {"id": "b", "text": "total volume multiplied by velocity of airflow.", "correct": false}, {"id": "c", "text": "total volume of air multiplied by relative density.", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The HMU of a FADEC engine increases fuel flow by increasing', '[{"id": "a", "text": "air flow through the compressor", "correct": false}, {"id": "b", "text": "hydraulic servo pressure", "correct": false}, {"id": "c", "text": "servo fuel pressure", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The EEC controls thrust by', '[{"id": "a", "text": "Moving the throttles", "correct": false}, {"id": "b", "text": "Increasing fuel flow", "correct": true}, {"id": "c", "text": "Controlling the bleed valves", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'When an EGT harness goes through a bulkhead disconnect you must ensure that', '[{"id": "a", "text": "pins and sockets are of the same material as the thermocouple leads.", "correct": true}, {"id": "b", "text": "the pins etc should be silver soldered and their connections properly made.", "correct": false}, {"id": "c", "text": "pins and sockets must be correctly crimped or braised and tested using a 250 Volt megger", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The physical law used for calibrating a thermocouple indicator depends on', '[{"id": "a", "text": "the materials of the sensing element.", "correct": true}, {"id": "b", "text": "the materials of the coils in the meter.", "correct": false}, {"id": "c", "text": "the range that the meter is required to read - i.e. operating scale", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'On a gas turbine engine, what is the fan driven by?', '[{"id": "a", "text": "HP turbine", "correct": false}, {"id": "b", "text": "LP turbine", "correct": true}, {"id": "c", "text": "IP turbine", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'The starter light is on during a start cycle (low voltage electrical starter).', '[{"id": "a", "text": "This is normal for 30 seconds, take no action", "correct": false}, {"id": "b", "text": "If the light stays on after 30 seconds action is required", "correct": false}, {"id": "c", "text": "Indicates electrical power is flowing to the starter", "correct": true}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'A DC starter motor disconnects due to', '[{"id": "a", "text": "current increasing switching off an overspeed relay", "correct": false}, {"id": "b", "text": "current decreasing switching off an overspeed relay", "correct": true}, {"id": "c", "text": "a centrifugal switch that acts like an overspeed relay", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Gas type fire wires operate by utilizing', '[{"id": "a", "text": "the change in the gas pressure", "correct": true}, {"id": "b", "text": "the change in the gas dilectric level", "correct": false}, {"id": "c", "text": "the change in the electrical resistance of the gas", "correct": false}]'::jsonb, '{B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M14.4'), 'Integrated fuel flow gives', '[{"id": "a", "text": "fuel flow and acceleration", "correct": false}, {"id": "b", "text": "average fuel flow", "correct": false}, {"id": "c", "text": "total fuel consumed", "correct": true}]'::jsonb, '{B2}');
